export const M09: SaintRec[] = [
  { key: "09-01", name: "Попразднство Успения Пресвятой Богородицы", kind: "feast", desc: "По совершении Господом спасения рода человеческого и вознесении Его на небо, пречистая и преблагословенная Дева Мария, Матерь Божия и Ходатаица нашего спасения, среди первых христиан жила довольно продолжительное время; Она исполнялась вели" },
  { key: "09-01", name: "Мч. Андрея Стратилата и с ним 2593-х мучеников", kind: "saint", desc: "Мч. Андрей Стратилат, римский военачальник при императоре Максимиане, уверовал во Христа. Возглавив небольшой отряд, он одержал победу над персами, убедив воинов отвергнуть языческих богов." },
  { key: "09-01", name: "Свт. Питирима, епископа Великопермского", kind: "saint", desc: "Свт. Питирим, епископ Пермский, возглавил кафедру после гибели свт. Герасима. Будучи ранее архимандритом Чудова монастыря, он ревностно проповедовал христианство среди зырян и вогулов, призывая к миру и отказу от грабежей." },
  { key: "09-01", name: "Св. Николая Лебедева, исп., пресвитера", kind: "saint", desc: "Сщисп. Николай Лебедев (1869–1933) родился в бедной семье пономаря в Тверской губернии. Окончив семинарию, стал священником в родных местах. Во Власьево основал знаменитое Общество трезвости, построил школу, закрыл кабаки, создал приюты для алкоголиков и беспризорных детей." },
  { key: "09-01", name: "прп. Марии Кореповой, исп.", kind: "saint", desc: "Присп. Мария (Корепова) родилась в 1877 году в Вологодской губернии. В 1919-1927 годах подвизалась в Спасо-Преображенском Севастьяновском монастыре Ярославской губернии до его закрытия." },
  { key: "09-01", name: "Донская", kind: "saint", desc: "Донская икона Пресвятой Богородицы была написана Феофаном Греком. В день Куликовской битвы (8 сентября 1380 года, на праздник Рождества Пресвятой Богородицы) икона находилась среди русского войска, подавая ему помощь, а после победы была пе" },
  { key: "09-02", name: "Попразднство Успения Пресвятой Богородицы", kind: "feast", desc: "По совершении Господом спасения рода человеческого и вознесении Его на небо, пречистая и преблагословенная Дева Мария, Матерь Божия и Ходатаица нашего спасения, среди первых христиан жила довольно продолжительное время; Она исполнялась вели" },
  { key: "09-02", name: "Прор. Самуила", kind: "saint", desc: "Пророк Самуил, последний судия Израиля (XII в. до Р.Х.), был дарован бесплодной Анне по молитвам. С 3 лет воспитывался при скинии под руководством первосвященника Илия." },
  { key: "09-02", name: "Прмч. Иосифа (Баранова), иеромонаха", kind: "saint", desc: "Прмч. Иосиф (Баранов) (1861-1918) – иеромонах, заведующий подворьем Толгского монастыря в Рыбинске. 20 августа 1918 года был арестован и на следующий день найден убитым на реке Черемхе (расстрелян богоборческой властью)." },
  { key: "09-02", name: "Александра Малиновского", kind: "saint", desc: "Сщмч. Александр Малиновский (1892-1918) родился в в Саратовской губернии. В 1917 году служил в селе Верх-Суксунское, где открыто выступал против гонений на Церковь." },
  { key: "09-02", name: "Льва Ершова", kind: "saint", desc: "Сщмч. Лев Ершов (1867-1918) родился в купеческой старообрядческой семье в Красноуфимске. Рукоположенный в священники в 1896 году, служил в Свято-Троицком соборе, став известным миссионером среди старообрядцев и преподавателем Закона Божия." },
  { key: "09-02", name: "Владимира Четверина", kind: "saint", desc: "Сщмч. Владимир Четверин (1874-1918) родился в благочестивой крестьянской семье в Симбирской губернии. Сначала работал учителем, затем в 36 лет был рукоположен в священники." },
  { key: "09-02", name: "сщмч. Николая Бирюкова, пресвитера", kind: "saint", desc: "Сщмч. Николай Бирюков, ревностный пастырь и проповедник, в годы гражданской войны призывал паству хранить верность Христу, осуждал разрушение храмов и гонения на Церковь." },
  { key: "09-02", name: "Обретение мощей сщмч. Гермогена (Долганева), епископа Тобольского", kind: "saint", desc: "Свт. Гермоген (Долганев), епископ Тобольский, родился в 1858 году в семье священника. Окончил Санкт-Петербургскую духовную академию, принял монашество и служил в разных епархиях." },
  { key: "09-03", name: "Попразднство Успения Пресвятой Богородицы", kind: "feast", desc: "По совершении Господом спасения рода человеческого и вознесении Его на небо, пречистая и преблагословенная Дева Мария, Матерь Божия и Ходатаица нашего спасения, среди первых христиан жила довольно продолжительное время; Она исполнялась вели" },
  { key: "09-03", name: "Ап. от 70-ти Фаддея", kind: "saint", desc: "Ап. от 70-ти Фаддей, уроженец сирийской Едессы, принял крещение от св. Иоанна Предтечи и стал учеником Христа. После Вознесения проповедовал в Сирии и Месопотамии, обратил в христианство князя Авгаря и жителей Едессы, совершая чудеса." },
  { key: "09-03", name: "прп. Авраамия Смоленского, архимандрита", kind: "saint", desc: "Прп. Авраамий Смоленский (XII-XIII вв.) с юности стремился к благочестию, раздал наследство и принял монашество. 30 лет подвизался в монастыре, став искусным проповедником и духовником." },
  { key: "09-03", name: "прп. Марфы Дивеевской (Милюковой)", kind: "saint", desc: "Прп. Марфа Дивеевская (в миру Мария Милюкова) родилась в 1810 году в крестьянской семье близ Дивеева. В 13 лет по благословению прп. Серафима Саровского поступила в Дивеевскую общину, где вела строгую подвижническую жизнь." },
  { key: "09-03", name: "Прп. Авраамия трудолюбивого, Печерского, в Ближних пещерах", kind: "saint", desc: "Прп. Авраамий Печерский (XIV в.), подвизался в Киево-Печерской лавре, в Ближних (Антониевых) пещерах, возможно, в сане игумена. Трудился на благо братии, за что и получил прозвание \"Трудолюбивый\"." },
  { key: "09-03", name: "прмч. Рафаила (Момчиловича), игумена Шишатовацкого (1941)", kind: "saint", desc: "Прмч. Рафаил (Момчилович) родился в 1875 году в сербской крестьянской семье. С 1935 года подвизался в Шишатовацком монастыре, где стал игуменом и создал множество икон." },
  { key: "09-03", name: "Сщмч. Александра Елоховского, пресвитера", kind: "saint", desc: "Сщмч. Александр Елоховский (1858-1918) родился в семье священника Ярославской губернии. Служил в селах Ярославской епархии, преподавал Закон Божий. В 1918 году арестован за \"антисоветскую агитацию\", возможно в связи с Ярославским восстанием." },
  { key: "09-03", name: "Павла Ягодинского", kind: "saint", desc: "Сщмч. Павел Ягодинский (1879-1937) родился в семье псаломщика в Симбирской губернии. Служил в селе Шугурово, отличался добротой, честностью и твердостью веры." },
  { key: "09-03", name: "Феодора Каллистова", kind: "saint", desc: "Сщмч. Федор Каллистов (1865-1937) родился в Пензенской губернии. Окончив духовную семинарию, с 1887 года служил священником. Трижды подвергался репрессиям: в 1930 году сослан в Сибирь на 3 года, в 1935 и 1937 годах арестовывался за сопротивление закрытию храма." },
  { key: "09-03", name: "прмч. Игнатия (Даланова), иеромонаха", kind: "saint", desc: "Прмч. Игнатий (Даланов) (1885-1942) родился в крестьянской семье в Витебской губернии. В 1911 году поступил в Оптину Пустынь, где принял постриг. После революции служил в храмах Козельского района." },
  { key: "09-03", name: "Светописанная (Светописанный образ)", year: "1903", kind: "saint", desc: "Явление Светописанного образа Пресвятой Богородицы в Русском на Афоне Свято-Пантелеимонове монастыре 3 сентября 2013 года исполнилось 110 лет явления Божией Матери в Свято-Пантелеимоновом монастыре на Афоне." },
  { key: "09-04", name: "Попразднство Успения Пресвятой Богородицы", kind: "feast", desc: "По совершении Господом спасения рода человеческого и вознесении Его на небо, пречистая и преблагословенная Дева Мария, Матерь Божия и Ходатаица нашего спасения, среди первых христиан жила довольно продолжительное время; Она исполнялась вели" },
  { key: "09-04", name: "сщмч. Горазда (Павлика), епископа Чешского и Моравско-Силезского", kind: "saint", desc: "Сщмч. Горазд (в миру Павлик Матей, 1879-1942) – чешский православный епископ и просветитель. Окончив католическую семинарию, служил священником, но в 1920 году перешел в православие." },
  { key: "09-04", name: "прп. Исаакия Оптинского", kind: "saint", desc: "Прп. Исаакий I Оптинский (Антимонов), выходец из благочестивой купеческой семьи Курска, в 1847 году, в возрасте 36 лет, поступил в Оптину пустынь. Пройдя путь от послушника до настоятеля обители (с 1862 г.), он 30 лет мудро управлял монастырём, при котором тот достиг духовного и хозяйственного расцвета." },
  { key: "09-04", name: "мц. Евлалии девы", kind: "saint", desc: "Св. Евлалия, 14-летняя христианка из Барселоны, во время гонений императора Диоклитиана сама явилась к правителю Дакиану и обличила его в идолопоклонстве." },
  { key: "09-04", name: "Макария (Гневушева), епископа Вяземского", kind: "saint", desc: "Сщмч. Макарий (Гневушев), известный миссионер, был хиротонисан во епископа Вяземского в январе 1917 года. Однако вскоре он был отправлен на покой как «несоответствующий духу времени»." },
  { key: "09-04", name: "Иоанна Бояршинова", kind: "saint", desc: "Священник села Сепычи Пермской губернии Иоанн Бояршинов был расстрелян новой властью 4 сентября 1918 года. Поводом послужил колокольный звон, которым он созывал прихожан на службу." },
  { key: "09-04", name: "Алексия Наумова", kind: "saint", desc: "Сщмч. Алексий Наумов служил в заводской церкви села Очера Пермской губернии. В 1918 году арестован по доносу за антисоветскую деятельность. После жестоких пыток и издевательств расстрелян красноармейцами 4 сентября того же года." },
  { key: "09-04", name: "Феодора (Смирнова), епископа Пензенского,", kind: "saint", desc: "Сщмч. Феодор, епископ Пензенский (в миру Владимир Смирнов), выпускник Казанской духовной академии. Неоднократно арестовывался и ссылался. В 1935 году хиротонисан во епископа Пензенского, но уже в 1936 году был арестован по стандартному обвинению в контрреволюционной деятельности." },
  { key: "09-04", name: "Василия Смирнова", kind: "saint", desc: "Сщмч. Василий Смирнов, выпускник Пензенской духовной семинарии, был арестован в 1930 году и отбывал срок на строительстве Беломорканала. После возвращения в Пензу он был вновь арестован в 1936 году вместе с епископом Феодором (Смирновым) по ложному обвинению." },
  { key: "09-04", name: "Гавриила Архангельского", kind: "saint", desc: "Сщмч. Гавриил Архангельский, выпускник Саратовской духовной семинарии, служил в храмах Пензенской епархии. В 1929 году был арестован и приговорен к 5 годам лагерей." },
  { key: "09-04", name: "Иоанна (Троянского), епископа Великолукского", kind: "saint", desc: "Сщмч. Иоанн (Троянский, 1862-1937) был арестован за активную проповедь, борьбу с обновленчеством и привлечение в церковь детей (в т.ч. раздачей конфет)." },
  { key: "09-04", name: "Алексия (Орлова), архиепископа Омского", kind: "saint", desc: "Сщмч. Алексий (Орлов, 1862-1937), архиепископ, после служения на различных кафедрах в 1931 году был назначен в Омск. В 1935 году владыка был арестован и сослан." },
  { key: "09-04", name: "Александра Ратьковского", kind: "saint", desc: "Сщмч. Александр Ратьковский (1870–1937) служил священником в Торопце. В 1931 году был арестован и сослан в Казахстан на три года. После возвращения продолжил служение." },
  { key: "09-04", name: "Михаила Люберцева", kind: "saint", desc: "Сщмч. Михаил Люберцев (1883–1937) служил диаконом, а затем священником в Тверской губернии. В 1931 году был арестован по делу о «нелегальном монастыре» и сослан на три года." },
  { key: "09-05", name: "Отдание праздника Успения Пресвятой Богородицы", kind: "feast", desc: "По совершении Господом спасения рода человеческого и вознесении Его на небо, пречистая и преблагословенная Дева Мария, Матерь Божия и Ходатаица нашего спасения, среди первых христиан жила довольно продолжительное время; Она исполнялась вели" },
  { key: "09-05", name: "Мч. Луппа Солунского", kind: "saint", desc: "Мч. Лупп, верный слуга вмч. Димитрия Солунского, после казни господина взял его перстень и омочил одежду в его крови. Этими святынями он творил в Солуни многие чудеса." },
  { key: "09-05", name: "Сщмч. Иринея, епископа Лионского", kind: "saint", desc: "Сщмч. Ириней Лионский (130–202 гг.), ученик свт. Поликарпа Смирнского, стал епископом Лиона после мученической кончины своего предшественника. Прославился как богослов, боровшийся с гностическими ересями." },
  { key: "09-05", name: "свт. Каллиника I, патриарха Константинопольского", kind: "saint", desc: "Свт. Каллиник, патриарх Константинопольский (693–705), отказался благословить императора Юстиниана II на разрушение храма Богородицы. Император жестоко отомстил: святителю выкололи глаза, отрезали язык и нос, а затем замуровали в каменной стене." },
  { key: "09-05", name: "Ефрема (Кузнецова), епископа Селенгинского", kind: "saint", desc: "Сщмч. Ефрем (Кузнецов, 1876–1918), епископ, выходец из забайкальских казаков, возглавлял Забайкальскую духовную миссию, активно обращал в православие бурят и корейцев." },
  { key: "09-05", name: "Вячеслава Закедского", kind: "saint", desc: "Сщмч. Вячеслав Закедский родился в 1879 году в семье священника, окончил Ярославскую духовную семинарию и стал учителем церковноприходской школы. В 1901 году рукоположен в диакона, служил в Рыбинском Преображенском соборе и преподавал Закон Божий." },
  { key: "09-05", name: "Иоанна Восторгова, пресвитеров", kind: "saint", desc: "Сщмч. Иоанн Восторгов (1864–1918) родился в семье священника, окончил Ставропольскую духовную семинарию. Служил в различных епархиях, занимался просветительской и миссионерской деятельностью, боролся с сектантством." },
  { key: "09-05", name: "мч. Николая Варжанского", kind: "saint", desc: "Мч. Николай Варжанский (1881–1918) – выпускник Московской духовной академии, активный миссионер и борец с сектантством. Организовал Варнавинское общество трезвости для рабочих, издавал православную литературу." },
  { key: "09-05", name: "Павла Гайдая", kind: "saint", desc: "Сщмч. Павел Гайдай (1886–1937) – священник из Одессы. Многократно арестовывался советской властью за активную пастырскую деятельность и сопротивление закрытию храмов." },
  { key: "09-05", name: "Иоанна Карабанова", kind: "saint", desc: "Сщмч. Иоанн Карабанов (1885–1937) был учителем, затем офицером, а после рукоположения служил священником в Орловской области. В 1932 году арестован за сопротивление закрытию храма и «контрреволюционную агитацию» против коллективизации." },
  { key: "09-06", name: "Сщмч. Евтихия, епископа, ученика ап. Иоанна Богослова", kind: "saint", desc: "Сщмч. Евтихий, ученик апостолов Иоанна Богослова и Павла, жил в I–II веках и проповедовал вместе с апостолами. Перенёс жестокие мучения: голод, пытки железом, огнём и зверями." },
  { key: "09-06", name: "Перенесение мощей свт. Петра Московского, митрополита Киевского и всея Руси, чудотворца", kind: "saint", desc: "Свт. Петр Московский, митрополит Киевский и всея Руси, родился на Волыни и с юности посвятил себя монашеству. Прославившись благочестием, в 1308 году был возведен на Русскую митрополию." },
  { key: "09-06", name: "Прп. Арсения Комельского, игумена", kind: "saint", desc: "Прп. Арсений Комельский родился в Москве в XV веке. С юности стремился к монашеской жизни, принял постриг в Троице-Сергиевой лавре. Нёс послушания на скотном дворе и в хлебне, отличался смирением." },
  { key: "09-06", name: "прп. Аристоклия (Амвросиева), старца Московского", kind: "saint", desc: "Прп. Аристоклий (Амвросиев, 1846–1918) – московский старец, афонский монах. Родился в Оренбурге, в детстве чудесно исцелён от паралича по молитвам Святителю Николаю." },
  { key: "09-06", name: "мч. Татиона Клавдиопольского (Вифинского)", kind: "saint", desc: "Мч. Татион пострадал в Вифинии при императоре Диоклитиане (284–305 гг.). После отказа отречься от христианства его заключали в темницу, подвергали истязаниям и избиению палками." },
  { key: "09-06", name: "мц. Сиры, девы Персидской", kind: "saint", desc: "Мц. Сира, жившая в VI веке в Персии, была дочерью жреца-огнепоклонника. Воспитанная в язычестве, она уверовала во Христа после встречи с христианками. Несмотря на уговоры родных, открыто отреклась от идолов." },
  { key: "09-06", name: "прп. Георгия Лимниота (Озерника)", kind: "saint", desc: "Прп. Георгий Лимниот, инок VIII века, пострадал за почитание икон при императоре-иконоборце Льве Исавре. После мучений (ему опалили голову и отрезали нос) скончался ок.", lifeId: "georgiy" },
  { key: "09-06", name: "равноап. Космы Этолийского, иеромонаха", kind: "saint", desc: "Равноап. Косма Этолийский (XVIII в.) – греческий проповедник, монах Афона. Получив благословение Константинопольского патриарха, он нёс слово Божие по всей Османской Греции." },
  { key: "09-06", name: "сщмч. Максима Горлицкого, пресвитера", kind: "saint", desc: "Сщмч. Максим Сандович, Горлицкий (1886–1914) – священник, миссионер в Закарпатье. Родился в униатской семье, принял православие. Рукоположен в 1911 году, служил в селе Граб, где активно проповедовал возвращение к православной вере." },
  { key: "09-06", name: "Собор Московских святых", kind: "feast", desc: "По благословению Святейшего Патриарха Алексия II в 1997 году установлено совершать празднование Собора Московских святых в воскресенье перед 8 сентября – днем Сретения Владимирской иконы Божией Матери." },
  { key: "09-06", name: "Сщмч. Михаила Воскресенского, пресвитера, и с ним 28-ми мучеников", kind: "saint", desc: "Сщмч. Михаил Воскресенский (1883–1918) служил священником в селе Бортсурманы. Был арестован карательным отрядом во время подавления крестьянского восстания в августе 1918 года." },
  { key: "09-06", name: "прмч. Серафима (Шахмутя), архимандрита", kind: "saint", desc: "Прмч. Серафим (Шахмуть, 1901–1946), архимандрит, родился в бедной крестьянской семье в Беларуси. С детства стремился к церковной жизни. В 1922 году поступил в Жировицкий монастырь, принял монашество." },
  { key: "09-06", name: "Петровская", year: "ок. 1306", kind: "saint", desc: "Петровская икона Пресвятой Богородицы называется так потому, что была написана святителем Петром , митрополитом Московским (&dagger; 21 декабря 1326 г.) в бытность его еще игуменом Ратского монастыря на Волыни." },
  { key: "09-07", name: "Перенесение мощей апостола Варфолом е я", year: "VI", kind: "feast", desc: "Перенесение мощей апостола Варфоломея было в конце VI века. Его апостольская деятельность и мученическая кончина воспоминаются Церковью 11 июня. Апостол Варфоломей пострадал за Христа в городе Альбане (ныне город Баку) в 71 году, где и находились его святые мощи." },
  { key: "09-07", name: "Ап. от 70-ти Тита, епископа Критского", kind: "saint", desc: "Апостол Тит (I в.), один из 70 учеников Христа, был уроженцем Крита, обращённым из язычества. Стал сподвижником апостола Павла, который рукоположил его во епископа Критского." },
  { key: "09-07", name: "свт. Мины, патриарха Цареградского", kind: "saint", desc: "Свт. Мина, патриарх Константинопольский (536–552), до избрания был пресвитером и надзирателем странноприимного дома. Стал патриархом после низложения еретика Анфима." },
  { key: "09-07", name: "Прмч. Моисея (Кожина), иеромонаха", kind: "saint", desc: "Прмч. Моисей (Кожин, 1868–1931), иеромонах, принял монашество в Соловецком монастыре, где служил до его закрытия в 1924 году. После возвращения в родное село продолжил пастырское служение." },
  { key: "09-07", name: "сщмч. Владимира Мощанского, пресвитера", kind: "saint", desc: "Сщмч. Владимир Мощанский (1866–1938) – протоиерей, служил в Тверской губернии. После закрытия храма в селе Спасском переехал в Вышний Волочек, где продолжал служить." },
  { key: "09-08", name: "Сретение Владимирской иконы Пресвятой Богородицы", kind: "icon", desc: "Владимирская икона Божией Матери написана Евангелистом Лукой на доске от стола, за которым трапезовал Спаситель с Пречистой Матерью и праведным Иосифом." },
  { key: "09-08", name: "блж. Марии Дивеевской (Фединой)", kind: "saint", desc: "Блж. Мария Дивеевская (Федина, 1870–1931) – юродивая Христа ради, подвижница Серафимо-Дивеевского монастыря. С детства странствовала, терпя голод и гонения." },
  { key: "09-08", name: "Прмч. Адриана Ондрусовского", kind: "saint", desc: "Прмч. Адриан Ондрусовский, в миру дворянин Андрей Завалишин, оставил имение после встречи с прп. Александром Свирским. Приняв постриг на Валааме, он основал Никольскую обитель на Ладожском озере." },
  { key: "09-08", name: "Собор святых Среднеазиатского митрополичьего округа", kind: "feast", desc: "Собор святых Среднеазиатского митрополичьего округа охватывает четыре страны – Кыргызстан, Узбекистан, Таджикистан и Туркмению. Поименный список Собора утвержден Священным Синодом Русской Православной Церкви 16 мая 2023 года." },
  { key: "09-08", name: "Собор святых Орловской митрополии", kind: "feast", desc: "23 июня 2021 г. Священный Синод Русской Православной Церкви благословил совершать празднование Собора Орловских святых. Дата празднования – 8 сентября." },
  { key: "09-08", name: "Сщмч. Петра Иевлева, пресвитера", kind: "saint", desc: "Сщмч. Петр Иевлев (1875–1918) – священник Преображенского собора в Невьянске (Пермская губерния). Был расстрелян 26 августа 1918 года в собственном доме." },
  { key: "09-08", name: "св. Георгия Коссова, исп., пресвитера", kind: "saint", desc: "Сщисп. Георгий Коссов (1855–1928) – протоиерей, служивший в селе Спас-Чекряк Орловской губернии. По благословению прп. Амвросия Оптинского построил каменный храм, создал приют для сирот, школы и больницу.", lifeId: "georgiy" },
  { key: "09-08", name: "сщмч. Виктора Элланского, пресвитера", kind: "saint", desc: "Сщмч. Виктор Элланский (1874–1937) – протоиерей, выпускник Киевской духовной академии. Близкий сподвижник митрополита сщмч. Владимира (Богоявленского)." },
  { key: "09-08", name: "Димитрия Морозова", kind: "saint", desc: "Мч. Димитрий Морозов (1875–1937) – крестьянин из Вятской губернии. Арестован в 1936 году за участие в «контрреволюционной группе церковников». Приговорён к 5 годам лагерей." },
  { key: "09-08", name: "Петра Бордана", kind: "saint", desc: "Мч. Петр Бордан (1895–1937) – крестьянин из Херсонской губернии. Арестован в 1936 году за отказ вступать в колхоз и приговорён к 3 годам лагерей. В Карагандинском лагере встретил единомышленника Димитрия Морозова." },
  { key: "09-08", name: "св. Романа Медведя, исп., пресвитера", kind: "saint", desc: "Сщисп. Роман Медведь (1874-1937) ‒ выпускник Санкт-Петербургской духовной академии, духовный сын св. Иоанна Кронштадтского. С 1901 года ‒ священник, служил в Санкт-Петербурге и Севастополе (окормлял моряков)." },
  { key: "09-08", name: "Обретение мощей свт. Николая (Могилевского), исп., митрополита Алма-Атинского", kind: "saint", desc: "Сщисп. Николай (Могилевский, 1877–1955) прошёл многолетние тюремные заключения и ссылки в 1920–1940-х годах, сохранив верность пастырскому служению. В 1945 году назначен архиепископом Алма-Атинским и Казахстанским." },
  { key: "09-08", name: "Умиление Псково-Печерская", year: "1524", kind: "saint", desc: "По преданию, Псково-Печерская икона Божией Матери «Умиление» была написана в 1521 году неким иеромонахом Арсением (Хитрошем) с иконы Божией Матери «Владимирская»." },
  { key: "09-09", name: "Прп. Пимена Великого", kind: "saint", desc: "Прп. Пимен Великий (ок. 340–450), египетский подвижник, проводил жизнь в строгом посте, молитве и достиг высот духовного совершенства. Прославился как мудрый наставник монахов." },
  { key: "09-09", name: "сщмч. Кукши и", kind: "saint", desc: "Прп. Кукша Печерский (XII в.) – монах Киево-Печерской лавры. Крестил язычников-вятичей (племя на территории современных Орловской и Калужской областей)." },
  { key: "09-09", name: "Пимена постника, Печерских, в Ближних пещерах", kind: "saint", desc: "Прп. Пимен постник (? – после 1114 года) – монах Киево-Печерской лавры, подвизался в Ближних пещерах. Согласно Киево-Печерскому патерику, предсказал кончину прп." },
  { key: "09-09", name: "свт. Осии исп., епископа Кордувийского", kind: "saint", desc: "Свт. Осия более 60 лет был епископом Кордовы (IV в.). Почитаемый императором Константином Великим, он был его советником и настоял на созыве I Вселенского (Никейского) Собора в 325 году, первым подписав его определения." },
  { key: "09-09", name: "свт. Ливерия исп., папы Римского", kind: "saint", desc: "Свт. Ливерий, папа Римский (с 352 г.), был поборником православия против ариан и защитником свт. Афанасия Александрийского. Император-арианин Констанций не смог склонить его к осуждению Афанасия, за что сослал Ливерия во Фракию." },
  { key: "09-09", name: "прп. Пимена Палестинского", kind: "saint", desc: "Прп. Пимен Палестинский, пустынник VI века, жил в пещере в пустыне Рува. Однажды зимой он рассказал пришедшему к нему иноку, что будет растерзан зверями в искупление греха юности: будучи пастухом, он не спас человека, которого растерзали его псы." },
  { key: "09-09", name: "мц. Анфисы (Анфусы) Новой", kind: "saint", desc: "Святая мученица Анфиса (Анфуса) Новая за смелое исповедание веры Христовой после жестоких пыток была утоплена в колодце. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текс" },
  { key: "09-09", name: "прп. Саввы Венефальского", kind: "saint", desc: "Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку 'Сообщить об ошибке' или Ctrl+Enter." },
  { key: "09-09", name: "Сщмч. Стефана Немкова, пресвитера, и с ним 18-ти мучеников", kind: "saint", desc: "Сщмч. Стефан Немков (1882–1918) окончил Симбирскую семинарию. Служил диаконом, затем священником в селе Деяново. В 1918 году карательный отряд чекистов арестовал его вместе с 18-ю прихожанами." },
  { key: "09-09", name: "сщмч. Павла Фокина, пресвитера", kind: "saint", desc: "Сщмч. Павел Фокин (1883–1918) окончил Пермскую духовную семинарию. Служил священником в Сретенской церкви села Мурзинского. После революции 1917 года был арестован за проповеди и отказ прекратить пастырскую деятельность." },
  { key: "09-09", name: "Иоанна Лебедева", kind: "saint", desc: "Сщмч. Иоанн Лебедев (1869–1937) окончил Рязанскую духовную семинарию. Служил священником в Христорождественском храме села Пронюхлово. После революции неоднократно преследовался властями за веру." },
  { key: "09-09", name: "Иоанна Смирнова", kind: "saint", desc: "Сщмч. Иоанн Смирнов (1873–1937) ‒ протоиерей, настоятель Никольского собора в Зарайске. Активно противостоял закрытию храмов советской властью. В 1930 году был арестован и сослан на три года." },
  { key: "09-09", name: "прмч. Мефодия (Иванова), игумена", kind: "saint", desc: "Прмч. Мефодий (Иванов, 1899–1937) родился в Симбирске. В 1923 году принял постриг в московском Покровском монастыре. Был рукоположен в иеромонаха. В 1929 году арестован за критику советской власти и осужден на три года ссылки." },
  { key: "09-09", name: "сщмч. Александра Цицерова, пресвитера", kind: "saint", desc: "Сщмч. Александр Цицеров (1884–1939) родился в крестьянской семье. Окончил семинарию, был учителем. В 1914 году рукоположен во священника, служил в Московской губернии." },
  { key: "09-10", name: "Прп. Моисея Мурина, иеромонаха", kind: "saint", desc: "Прп. Моисей Мурин, живший в IV веке, был эфиопом по происхождению и в молодости предводителем разбойников. Раскаявшись, он ушёл в пустынный монастырь, где вёл суровую аскетическую жизнь, борясь с плотскими страстями." },
  { key: "09-10", name: "Обретение мощей прп. Иова Почаевского, игумена", kind: "saint", desc: "Прп. Иов Почаевский (в миру Иван Железо, XVI–XVII вв.) ‒ игумен Почаевской лавры. С юности посвятил себя монашеской жизни. Активно защищал православие от католического влияния и унии." },
  { key: "09-10", name: "Собор преподобных отцов Киево-Печерских, в Дальних пещерах (прп. Феодосия) почивающих", kind: "feast", desc: "Чистаго ради и непорочнаго твоего жития,/ Богоносе отче Игнатие,/ приемый от Господа чудотворныя дары исцеляти немощныя,/ исцели, молим тя, и немощи наша,// моля о нас Единаго Человеколюбца." },
  { key: "09-10", name: "прп. Саввы Крыпецкого, Псковского", kind: "saint", desc: "Прп. Савва Крыпецкий (XV в.) пришел в Россию, вероятно, с Афона или из Сербии. Подвизался в уединении на болотистой местности, где основал обитель с строгим уставом." },
  { key: "09-10", name: "прав. Анны Пророчицы, дщери Фануилевой, встретившей Господа Иисуса Христа в храме Иерусалимском", kind: "saint", desc: "Св. Анна Пророчица, 84-летняя вдова из колена Асирова, удостоилась встретить Младенца Иисуса в храме при Сретении. За свою благочестивую жизнь она получила от Бога дар пророчества." },
  { key: "09-10", name: "вмц. Шушаник (Шушаники), царицы Ранской (475)", kind: "saint", desc: "Вмц. Шушаника (V век), княгиня Ранская, была дочерью армянского военачальника Вардана. Вышла замуж за правителя Варскена, который отрёкся от христианства и стал огнепоклонником." },
  { key: "09-10", name: "Сщмч. Алексия Будрина, пресвитера", kind: "saint", desc: "Сщмч. Алексий Будрин (1861–1918) ‒ протоиерей, выпускник Пермской духовной семинарии. Много лет служил в храмах Пермской губернии, был законоучителем, членом Государственной думы IV созыва." },
  { key: "09-10", name: "Казанских: Сергия (Зайцева), архимандрита", kind: "saint", desc: "Прмч. Сергий (Зайцев, 1863–1918) ‒ настоятель Успенского Зилантова монастыря в Казани. После революции 1917 года монастырь был занят войсками. 10 сентября 1918 года красноармейцы ворвались в обитель и расстреляли всю братию во главе с архимандритом Сергием." },
  { key: "09-10", name: "сщмч. Александра Медведева, диакона", kind: "saint", desc: "Сщмч. Александр Медведев (1889–1918) служил диаконом в селе Больше-Трифонском Ирбитского уезда. В годы гонений продолжал служение, несмотря на опасность." },
  { key: "09-10", name: "сщмч. Николая Георгиевского, пресвитера", kind: "saint", desc: "Сщмч. Николай Георгиевский (1865–1931) ‒ протоиерей, служил в Космо-Дамианском храме в Болшево, был благочинным Мытищинского района. Активно сопротивлялся закрытию храма безбожными властями в 1930 году." },
  { key: "09-10", name: "сщмч. Василия Сокольского, пресвитера", kind: "saint", desc: "Сщмч. Василий Сокольский (1878–1937) ‒ выпускник Казанской духовной академии, магистр богословия. Служил священником в Петрограде, активно противостоял обновленческому расколу." },
  { key: "09-11", name: "Усекновение главы Пророка, Предтечи и Крестителя Господня Иоанна", kind: "feast", desc: "О мученической кончине Предтечи Господня в 32 году по Рождестве Христовом повествуют Евангелия по Матфею ( Мф.14:1-12 ) и Марку ( Мк.6:14-29 ). Однако Священное предание Апостольской Церкви сохранило некоторые подробности этих событий, происходивших незадолго до Распятия и Воскресения Христова." },
  { key: "09-12", name: "прп. Александра Свирского, игумена", kind: "saint", desc: "Прп. Александр Свирский (1448–1533) ‒ великий русский святой, основатель Свято-Троицкого монастыря на реке Свири. Прославился аскетическими подвигами, прозорливостью и чудотворениями." },
  { key: "09-12", name: "Обретение мощей блгв. кн. Даниила Московского", kind: "saint", desc: "Св. блгв. кн. Даниил Московский (1261–1303) ‒ младший сын св. Александра Невского, основатель Московского княжества. Прославился благочестием, миротворчеством и мудрым правлением." },
  { key: "09-12", name: "Перенесение мощей блгв. вел. кн. Александра Невского, в схиме Алексия", kind: "saint", desc: "11 июля (переходящая) - Соборы Новгородских, Санкт-Петербургских, Псковских и Волгоградских святых Св. блгв. кн. Александр Невский (1221–1263) ‒ новгородский князь, великий полководец и дипломат." },
  { key: "09-12", name: "Прп. Христофора Римлянина", kind: "saint", desc: "Прп. Христофор Римлянин (VI век) ‒ палестинский подвижник. Подвизался в монастыре прп. Феодосия Великого, где проводил ночи в молитве в пещере. Позже ушёл на Синайскую гору, где 50 лет совершал аскетические подвиги." },
  { key: "09-12", name: "прп. Фантина чудотворца, в Солуни", kind: "saint", desc: "Прп. Фантин Солунский (IX–X вв.) ‒ греческий святой, уроженец Калабрии. С детства воспитывался в монастыре, с юности посвятил себя аскетическим подвигам: странствовал по пустыням, соблюдал строгий пост и безмолвие." },
  { key: "09-12", name: "Святителей Сербских: Саввы I", kind: "saint", desc: "Свт. Савва Сербский (ок. 1169‒1237) ‒ первый архиепископ автокефальной Сербской Православной Церкви, сын св. правителя Стефана Немани. В 17 лет принял монашество на Афоне, где основал Хиландарский монастырь." },
  { key: "09-12", name: "Арсения I", kind: "saint", desc: "Свт. Арсений Сербский (XIII в.) ‒ ближайший ученик и преемник св. Саввы Сербского. По его благословению перенёс кафедру Сербской архиепископии в город Печ (Косово), основав там монастырь." },
  { key: "09-12", name: "Саввы II", kind: "saint", desc: "Свт. Савва II (ок. 1200–1271) ‒ третий архиепископ Сербский, племянник св. Саввы Сербского и сын св. короля Стефана Первовенчанного. Отказавшись от светской власти, принял монашество на Афоне в Хиландаре, совершил паломничество в Иерусалим." },
  { key: "09-12", name: "Евстафия I", kind: "saint", desc: "Свт. Евстафий, архиепископ Сербский (XIII век), родился в благочестивой семье, принял монашество в монастыре Архангела Михаила в Черногории. Совершил паломничество в Иерусалим и на Афон, где стал игуменом Хиландарского монастыря." },
  { key: "09-12", name: "Иакова", kind: "saint", desc: "Свт. Иаков, архиепископ Сербский (XIII век), преемник свт. Евстафия. Отличался ревностью в вере и добродетельной жизнью. Скончался 3 февраля 1292 года." },
  { key: "09-12", name: "Никодима", kind: "saint", desc: "Свт. Никодим, архиепископ Сербский (†1324), бывший игумен Хиландарского монастыря на Афоне. Учёный богослов и переводчик: перевёл на сербский язык Иерусалимский устав и дополнил синаксарь поминовением сербских святых." },
  { key: "09-12", name: "Даниила II", kind: "saint", desc: "Свт. Даниил II, архиепископ Сербский (XIII–XIV вв.). Выходец из знатного рода, в юности тайно покинул королевский двор и принял монашество. Прославился аскетизмом, был игуменом Хиландарского монастыря на Афоне, затем епископом Холмским." },
  { key: "09-12", name: "Иоанникия II", kind: "saint", desc: "Свт. Иоанникий (XIV в.), патриарх Сербский. Родом из Призрена, ранее служил секретарём при короле Карле Сербском. В 1339 году стал архиепископом, а в 1346 году возведён в патриархи." },
  { key: "09-12", name: "Ефрема II", kind: "saint", desc: "Свт. Ефрем (1312-1400), 3-й патриарх Сербский, известный своей духовной мудростью и усилиями по укреплению Церкви в трудный период османского нашествия." },
  { key: "09-13", name: "Положение честн о го пояса Пресвятой Богородицы", year: "395–408", kind: "feast", desc: "Пояс Пресвятой Богородицы был одной из трех главных святынь Константинополя , связанных с земной жизнью Божией Матери; кроме Пояса, в Царьграде хранились Риза (точнее, мафорий) Девы Марии и икона Божией Матери Одигитрии , написанная, по преданию, евангелистом Лукой." },
  { key: "09-13", name: "Сщмч. Киприана, епископа Карфагенского", kind: "saint", desc: "Сщмч. Киприан Карфагенский (ок. 200–258) – епископ и богослов. Будучи знатным язычником и ритором, он обратился в христианство, раздал имение нищим и в 248 году был избран епископом Карфагена." },
  { key: "09-13", name: "свт. Геннадия, патриарха Цареградского", kind: "saint", desc: "Свт. Геннадий был патриархом Константинопольским с 458 года. Он славился кротостью, чистотой и силой молитвы. Геннадий созвал Поместный Собор для осуждения ереси Евтихия и борьбы с симонией." },
  { key: "09-13", name: "Собор святых Нижегородской митрополии", kind: "feast", desc: "Празднование Собора святых Нижегородской митрополии в день Собора Нижегородских святых (в 1-е воскресенье после 8 сентября) внесено в месяцеслов по благословению Святейшего Патриарха Кирилла от 6 октября 2020 года." },
  { key: "09-13", name: "Собор Саратовских святых", kind: "feast", desc: "Празднование установлено в 2011 году по благословению патриарха Московского и всея Руси Кирилла. Днесь да празднует земля Саратовская/ и да красуется песненными добротами,/ яко ныне прииде день всекраснаго торжества,/ память общая святых, п" },
  { key: "09-13", name: "Собор новомучеников Яс е новацких (1941–1944)", year: "Серб.", kind: "feast", desc: "Ясеновац (хорв. Jasenovac) – система лагерей смерти, созданная усташами (хорватскими фашистами) в августе 1941 года. Располагалась на территории Независимого Хорватского государства, сотрудничавшего с нацистской Германией, в 60 км от Загреба." },
  { key: "09-13", name: "Александра Любимова, пресвитера,", kind: "saint", desc: "Священник Александр Любимов (1884–1918) и диакон Владимир Двинский были священнослужителями Ильинского храма в Псковской губернии. После революции продолжали служение, проповедовали и призывали паству защищать церковное имущество." },
  { key: "09-13", name: "Владимира Двинского, диакона", kind: "saint", desc: "Священник Александр Любимов и диакон Владимир Двинский служили в Ильинском храме Псковской губернии. После революции они продолжали проповедовать. 10 сентября 1918 года оба были арестованы по доносу, кратко допрошены петроградскими чекистами и в тот же день расстреляны в роще за Полонским погостом." },
  { key: "09-13", name: "Михаила Косухина", kind: "saint", desc: "Сщмч. Михаил Косухин (1858–1937) был священником в селе Дымцево Тверской области. После революции, несмотря на преклонный возраст и гонения, он продолжал служить и проповедовать." },
  { key: "09-13", name: "Мирона Ржепика", kind: "saint", desc: "Сщмч. Мирон Ржепик (1885–1937) родился в Волынской губернии, окончил Московскую духовную академию. После революции служил священником в Подмосковье. В 1930 году был арестован и осуждён на 10 лет лагерей по обвинению в контрреволюционной деятельности." },
  { key: "09-13", name: "сщмч. Димитрия Смирнова, пресвитера", kind: "saint", desc: "Сщмч. Димитрий Смирнов (1868–1938) был священником в Московской области. В 1938 году его арестовали по ложному обвинению в контрреволюционной деятельности за проповеди и совершение молебнов." },
  { key: "09-14", name: "Начало индикта – церковное новолетие", kind: "feast", desc: "Без сомнения, все хорошо знают, что мы празднуем Новый год в январе, причём, дважды, и наша высокая логика недоступна рациональным иноземцам, не могущим понять, как это «новый» год может быть одновременно и «старым»? Но, оказывается, тот ян" },
  { key: "09-14", name: "Сщмч. Аифала, диакона", kind: "saint", desc: "Епископ Акепсим, пресвитер Иосиф и диакон Аифал служили в Персии IV века. Во время гонений царя Сапора II их схватили за отказ отречься от веры. После трёх лет жестоких пыток и заключения они предстали перед царём и вновь отвергли язычество." },
  { key: "09-14", name: "Мцц. 40 дев постниц и сщмч. Аммуна Ираклийского, диакона, учителя их", kind: "saint", desc: "Святые 40 дев и диакон Аммун приняли мученическую смерть в Адрианополе в начале IV века при императоре Ликинии. Они отказались отречься от веры и принести жертву идолам." },
  { key: "09-14", name: "прав. Иисуса Навина", kind: "saint", desc: "Св. Иисус Навин (XVI в. до Р.X.) по смерти пророка Моисея возглавил израильский народ и завоевал Обетованную землю. Господь явил через него великие чудеса: переход через Иордан как по суше, падение стен Иерихона и остановку солнца во время битвы." },
  { key: "09-14", name: "прп. Дионисия Малого (до 556)", kind: "saint", desc: "Прп. Дионисий Малый (ок. 470 ‒ между 537 и 556), скиф по происхождению, был монахом в Риме. Будучи учёным-богословом и переводчиком, он составил сборник соборных правил и папских декреталий." },
  { key: "09-14", name: "Прмц. Татианы Грибковой, послушницы", kind: "saint", desc: "Прмц. Татиана (Грибкова, 1879–1937), послушница, была насельницей Казанского Головинского монастыря под Москвой. После его закрытия в 1925 году поселилась в родном селе." },
  { key: "09-14", name: "мц. Наталии Козловой", kind: "saint", desc: "Мц. Наталия Козлова (1895–1937) была крестьянкой из села Чурики Рязанской губернии, матерью восьмерых детей и церковной старостой. После гибели мужа от рук коммунистов и конфискации имущества она продолжала активно защищать веру: организовы" },
  { key: "09-14", name: "Миасинская", year: "864", kind: "saint", desc: "Миасинская (Азуровская) икона Божией Матери получила свое название от Миасинской обители, находившейся в Армении. В первые века христианства Миасинская долина, в которой позже был основан монастырь, была густо заселена язычниками." },
  { key: "09-14", name: "Черниговская-Гефсиманская", year: "1869", kind: "saint", desc: "Черниговская-Гефсиманская икона Божией Матери является списком с прославленной Черниговской-Ильинской иконы Божией Матери, которая находилась в Троицком Ильинском монастыре близ Чернигова, на Болдиной горе, где в XI в." },
  { key: "09-14", name: "Александрийская", kind: "saint", desc: "Название иконы происходит от египетского города Александрии – одного из центров раннего христианства. Сведений об этом образе сохранилось немного, и сохранившаяся информация противоречива." },
  { key: "09-14", name: "Август о вская", year: "1914", kind: "saint", desc: "28 февраля 2008 года Святейший Патриарх Московский и всея Руси Алексий по представлению Издательского Совета Русской Православной Церкви благословил внести в официальный месяцеслов празднование в честь Августовской иконы Божией Матери." },
  { key: "09-14", name: "Всеблаженная", year: "в Казани", kind: "saint", desc: "Икона Пресвятой Богородицы, именуемая «Всеблаженная», или «Памакариста», прислана в 1905 году Святейшим Патриархом Константинопольским Иоакимом III в благословение и утешение граду Казани после святотатственного похищения из соборного храма" },
  { key: "09-15", name: "свт. Иоанна Постника, патриарха Цареградского", kind: "saint", desc: "Свт. Иоанн Постник, патриарх Константинопольский, прославился крайним воздержанием и щедростью к бедным. Несмотря на желание избежать высокого сана, был избран патриархом по Божьему указанию." },
  { key: "09-15", name: "Антония", kind: "saint", desc: "Основатель Киево-Печерской Лавры прп. Антоний, уроженец Любеча (вблизи Чернигова), принял постриг на Афоне, а затем по послушанию игумену вернулся на Русь, поселившись в 1051 году в пещере близ Киева.", lifeId: "pecherskie" },
  { key: "09-15", name: "Феодосия (1074) Печерских", kind: "saint", desc: "Прпп. Антоний и Феодосий Печерские ‒ основатели русского монашества. Св. Антоний (ок. 983-1073), уроженец Любеча, принял постриг на Афоне, затем вернулся на Русь и поселился в пещере близ Киева (1051 г.).", lifeId: "pecherskie" },
  { key: "09-15", name: "Обретение мощей прп. Феодосия Тотемского", kind: "saint", desc: "Прп. Феодосий Тотемский (Суморин), вологжанин, с юности вел благочестивую жизнь. Овдовев, он ушел в Прилуцкий монастырь. Позже, направленный в Тотьму, испросил разрешения основать там новую обитель и стал её настоятелем." },
  { key: "09-15", name: "мчч. 3628-ми в Никомидии", year: "III–IV", kind: "saint", desc: "Три тысячи шестьсот двадцать восемь (по другим три тысячи шестьсот восемь) святых мучеников пострадали в Никомидии во время гонения Максимиана (290 г. н.э.)." },
  { key: "09-15", name: "Дамаскина (Цедрика), епископа Стародубского,", kind: "saint", desc: "Сщмч. Дамаскин (Дмитрий Цедрик), епископ Стародубский, родился в 1877 году. Монах, миссионер, участник Первой мировой войны. После революции неоднократно арестовывался." },
  { key: "09-15", name: "Евфимия Горячева", kind: "saint", desc: "Сщмч. Евфимий Горячев родился в 1884 году в бедной крестьянской семье. Стал священником и служил в селах Красноярского края. В годы гонений стойко противостоял обновленцам, за что неоднократно арестовывался и провёл три года в лагере." },
  { key: "09-15", name: "Иоанна Мельниченко", kind: "saint", desc: "Сщмч. Иоанн Мельниченко (1889-1937) был учителем, а в 1922 году рукоположен в священники. Арестован в 1935 году и осуждён на 7 лет лагерей за «контрреволюционную агитацию»." },
  { key: "09-15", name: "Иоанна Смоличева", kind: "saint", desc: "Сщмч. Иоанн Смоличев родился в 1889 году в Черниговской губернии. Был рукоположен во иереи в 1924 году епископом Дамаскином (Цедриком). Дважды арестовывался за «контрреволюционную деятельность»: в 1930 году (5 лет лагерей) и в 1936 году по делу епископа Дамаскина (вновь 5 лет ИТЛ)." },
  { key: "09-15", name: "Владимира Моринского", kind: "saint", desc: "Сщмч. Владимир Моринский (1883-1937) был регентом и учителем пения. Рукоположен в священники в 1934 году. Арестован в 1935 году за «антисоветскую агитацию» и осуждён на 3 года лагерей." },
  { key: "09-15", name: "Виктора Басова", kind: "saint", desc: "Сщмч. Виктор Басов родился в 1892 году в семье диакона. Рукоположен в священники в 1925 году. Арестован в 1935 году за «антисоветскую агитацию» и помощь крестьянам в составлении жалоб, осуждён на 5 лет лагерей." },
  { key: "09-15", name: "Феодота Шатохина", kind: "saint", desc: "Сщмч. Феодот Шатохин родился в 1888 году. Был рукоположен в священники. Дважды арестовывался: в 1926 году за «распространение религиозных убеждений» (1 год тюрьмы) и в 1935 году в Донецке (7 лет лагерей)." },
  { key: "09-15", name: "Петра Новосельского", kind: "saint", desc: "Сщмч. Пётр Новосельский родился в 1883 году в семье диакона. Окончил духовную семинарию, принял сан священника. Дважды арестовывался: в 1929 году (3 года ссылки в Туруханский край) и в 1935 году за организацию богослужения 1 мая с целью «отвлечения от демонстрации» (3 года лагерей в Карлаге)." },
  { key: "09-15", name: "Стефана Ярошевича", kind: "saint", desc: "Сщмч. Стефан Ярошевич родился в 1883 году в семье псаломщика. Служил священником в селе Горячевка Винницкой области. Арестован в 1935 году и осуждён на 6 лет лагерей." },
  { key: "09-16", name: "прп. Феоктиста Палестинского, спостника Евфимия Великого, игумена", kind: "saint", desc: "Прп. Феоктист был игуменом и сопостником прп. Евфимия Великого. Они вместе подвизались в Фаранской обители, а затем удалились в Кутиллийскую пустыню, где жили в пещере в посте и молитве." },
  { key: "09-16", name: "блж. Иоанна Власатого, Ростовского чудотворца", kind: "saint", desc: "Блж. Иоанн Власатый, Милостивый, чудотворец, подвизался в Ростове во времена Ивана Грозного. Имел «власы на главе велики», потому и назывался Власатым." },
  { key: "09-16", name: "Св. Фивы Кенхрейской (Коринфской), диаконисы", kind: "saint", desc: "Св. Фива Кенхрейская, упомянутая апостолом Павлом в Послании к Римлянам (16:1-2), была диакониссой в портовом городе Кенхреи близ Коринфа. О сей святой упоминает апостол Павел в Послании к Римлянам." },
  { key: "09-16", name: "мц. Василиссы Никомидийской", kind: "saint", desc: "Мц. Василисса Никомидийская, девятилетняя отроковица, пострадала за веру при императоре Диоклетиане в 309 году. Правитель Александр подверг её жестоким мучениям, пытаясь заставить отречься от Христа, но по молитве святая осталась невредимой." },
  { key: "09-16", name: "сщмч. Аристиона, епископа Александрийского", kind: "saint", desc: "Сщмч. Аристион, епископ Александрии Малой, родился в Апамее. Крещён в детстве. За добродетельную жизнь был избран епископом. Проповедовал о тленности земного и вечности небесных благ." },
  { key: "09-16", name: "свт. Иоанникия II, патриарха Сербского", kind: "saint", desc: "Свт. Иоанникий (XIV в.), патриарх Сербский. Родом из Призрена, ранее служил секретарём при короле Карле Сербском. В 1339 году стал архиепископом, а в 1346 году возведён в патриархи." },
  { key: "09-16", name: "Пимена (Белоликова), епископа Верненского", kind: "saint", desc: "Сщмч. Пимен (Белоликов), епископ Семиреченский и Верненский, родился в 1879 году. Выпускник Киевской духовной академии, миссионер, проповедовал среди сирийцев в Персии." },
  { key: "09-16", name: "Сергия Феноменова", kind: "saint", desc: "Сщмч. Сергий Феноменов, протоиерей, служил в Крепостной церкви Усть-Каменогорска и был войсковым священником местного гарнизона. В 1918 году, после захвата власти большевиками, он был расстрелян на глазах у своей семьи на Комендантском острове." },
  { key: "09-16", name: "Василия Колмыкова", kind: "saint", desc: "Сщмч. Василий Колмыков родился в 1866 году. Служил настоятелем храма в селе Мещанском, затем в станице Подгорненской Семиреченской области. Погиб в 1918 году во время репрессий против духовенства в Семиречье." },
  { key: "09-16", name: "Филиппа Шатова", kind: "saint", desc: "Сщмч. Филипп Шатов, протоиерей, был преподавателем миссионерской школы в станице Сарканд Семиреченской области. В 1918 году большевики, захватившие село, заперли его в здании школы и сожгли заживо." },
  { key: "09-16", name: "Владимира Дмитревского", kind: "saint", desc: "Сщмч. Владимир Дмитревский родился в 1876 году в семье псаломщика. Служил священником в Семиреченской области. В 1918 году погиб при столкновении крестного хода с большевистской демонстрацией." },
  { key: "09-16", name: "прмч. Мелетия (Голоколосова), иеромонаха", kind: "saint", desc: "Прмч. Мелетий (Голоколосов), иеромонах, был постриженником Глинской пустыни. После разорения Иссык-Кульского монастыря служил в Копальском уезде Семиреченской области." },
  { key: "09-16", name: "Андрея Дольникова", kind: "saint", desc: "Сщмч. Андрей Дольников служил священником в Семиреченской области. В сентябре 1920 года арестован по обвинению в «контрреволюционной деятельности» и невыполнении хлебозаготовок." },
  { key: "09-16", name: "Феофана Соколова", kind: "saint", desc: "Сщмч. Феофан Соколов, митрофорный протоиерей, родился в 1875 году. Был инспектором церковноприходских школ Семиреченской области, членом Духовной Консистории и настоятелем Покровской церкви в Верном (ныне Алма-Ата)." },
  { key: "09-17", name: "прор. Моисея Боговидца", kind: "saint", desc: "Св. Моисей Боговидец, великий пророк и законодатель, родился в Египте ок. 1570 г. до Р.Х. Воспитан дочерью фараона, стал орудием Божиим в освобождении еврейского народа из рабства." },
  { key: "09-17", name: "Обретение мощей свт. Иоасафа, епископа Белгородского", kind: "saint", desc: "Свт. Иоасаф (Горленко) родился в 1705 году в Малороссии. Окончил Киевскую духовную академию, принял монашество. Прошел путь от иеродиакона до епископа Белгородского (с 1748 года)." },
  { key: "09-17", name: "свт. Митрофана, в схиме Макария, епископа Воронежского", kind: "saint", desc: "Свт. Митрофан Воронежский (1623-1703) – выдающийся архипастырь XVII века. Родился во Владимирской земле, 40 лет прожил в миру, овдовев, принял монашество." },
  { key: "09-17", name: "Собор святых Воронежской митрополии", kind: "feast", desc: "На епархиальном собрании Воронежской епархии, состоявшемся в Воронеже 28 февраля 2002 года по инициативе митрополита Воронежского Мефодия, было единодушно установлено празднование дня соборной памяти всех святых Воронежской епархии." },
  { key: "09-17", name: "прмч. Парфения, игумена Кизилташского", kind: "saint", desc: "Прмч. Парфений родился в 1815 году. Принял монашество, служил иеромонахом. Во время Крымской войны перед лицом смертельной опасности неотлучно исповедовал и причащал раненых воинов." },
  { key: "09-17", name: "Мц. Ермионии, дщери ап. Филиппа диакона", kind: "saint", desc: "Мц. Ермиония, дочь апостола Филиппа, жила во II веке. Владея врачебным искусством, помогала христианам. При императорах Траяне и Адриане её неоднократно пытались заставить отречься от Христа, подвергая жестоким пыткам: бичеванию, пытке раскалёнными гвоздями, кипящей смолой и раскалённой сковородой." },
  { key: "09-17", name: "мч. Вавилы Никомидийского и с ним 84-х отроков", kind: "saint", desc: "Мч. Вавила Никомидийский и 84 его воспитанника пострадали при императоре Максимиане (284-305 гг.). Старец Вавила обучал детей христианской вере. За отказ принести жертву идолам все были преданы мучениям." },
  { key: "09-17", name: "сщмч. Петра (Зимонича), митрополита Дабро-Боснийского (1941)", kind: "saint", desc: "Сщмч. Пётр (Зимонич), митрополит Дабро-Боснийский, родился в 1866 году в Герцеговине. Активный церковный и национальный деятель, восстанавливал храмы и школы, защищал сербскую автономию." },
  { key: "09-17", name: "Григория (Лебедева), епископа Шлиссельбургского", kind: "saint", desc: "Сщмч. Григорий (Лебедев), епископ Шлиссельбургский, родился в 1878 году в Коломне. Окончил Казанскую духовную академию, принял монашество. В 1923 году хиротонисан во епископа, стал наместником Александро-Невской лавры." },
  { key: "09-17", name: "Сергия (Дружинина), епископа Нарвского", kind: "saint", desc: "Сщмч. Сергий (Дружинин) родился в 1863 году. Был духовником великих князей Константиновичей. В 1924 году хиротонисан во епископа Нарвского. Активный участник иосифлянского движения, отвергшего Декларацию митр." },
  { key: "09-17", name: "Павла Васильевского", kind: "saint", desc: "Сщмч. Павел Васильевский родился в 1881 году в семье церковнослужителя. Служил в армии во время Первой мировой войны. После демобилизации стал священником, служил в храмах Тверской губернии." },
  { key: "09-17", name: "Иоанна Василевского", kind: "saint", desc: "Сщмч. Иоанн Василевский родился в 1869 году. Окончил Тверскую духовную семинарию, служил священником в храмах Тверской губернии. Неоднократно преследовался советской властью: в 1922 году был арестован за сопротивление изъятию церковных ценностей, но освобождён по кассации." },
  { key: "09-17", name: "Николая Лебедева", kind: "saint", desc: "Сщмч. Николай Лебедев родился в 1867 году в семье священника. Окончил Тверскую духовную семинарию, служил священником в селе Русская Кошева. В 1937 году, в возрасте 70 лет, был арестован по обвинению в «антисоветской агитации» и участии в «контрреволюционной группировке духовенства»." },
  { key: "09-17", name: "Николая Сретенского", kind: "saint", desc: "Сщмч. Николай Сретенский родился в 1867 году в семье священника. Окончил Тверскую духовную семинарию, с 1890 года служил в храме Бежецкого Благовещенского монастыря." },
  { key: "09-18", name: "прмч. Афанасия Брестского, игумена", kind: "saint", desc: "Прмч. Афанасий Брестский (1597-1648) – белорусский святой, ярый защитник Православия в эпоху насаждения Брестской унии. Приняв монашество, он стал игуменом Брестского Симеонова монастыря, где открыто обличал унию." },
  { key: "09-18", name: "Убиение блгв. кн. Глеба, во Святом Крещении Давида", kind: "saint", desc: "Свв. благоверные князья Борис и Глеб (†1015) ‒ младшие сыновья св. князя Владимира. Воспитанные в христианской вере, они предпочли смерть междоусобной войне: Борис отказался бороться за престол против старшего брата Святополка, а Глеб смиренно принял смерть, зная о судьбе брата." },
  { key: "09-18", name: "мч. Сарвила", kind: "saint", desc: "Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку 'Сообщить об ошибке' или Ctrl+Enter." },
  { key: "09-18", name: "мц. Раисы (Ираиды) девы", kind: "saint", desc: "Св. мц. Ираида Александрийская, увидев корабль с заключёнными в оковы христианами, добровольно присоединилась к ним. Когда судно прибыло в египетский город Антиполь, она первая приняла жестокие мучения и была усечена мечом." },
  { key: "09-18", name: "мч. Авдия (Авида) в Персии", kind: "saint", desc: "Мч. Авдий (Авид) пострадал в Персии при царе Издигерде I (V век) за отказ отречься от Христа и поклониться солнцу и огню. Мученик Авдий (или Авид) пострадал в Персии при царе Издигерде I за отказ отречься от Христа и поклониться солнцу и огню." },
  { key: "09-18", name: "Мч. Евфимия Кочева", kind: "saint", desc: "Мч. Евфимий Кочев (1867-1937) родился в коми-крестьянской семье. Был церковным старостой Сретенского храма в селе Вильгорт. В 1937 году активно сопротивлялся закрытию церкви, собирал подписи верующих." },
  { key: "09-18", name: "прп. Александра (Уродова), исп., архимандрита", kind: "saint", desc: "Исповедник Александр (Уродов, 1882-1961), архимандрит ‒ уроженец Пензенской губернии, с 1911 года монах Санаксарского монастыря, где в 1915 году стал игуменом." },
  { key: "09-18", name: "Оршанская", year: "1631", kind: "saint", desc: "Икона была явлена чудесным образом в 1631 году при основании мужского Кутеинского Свято-Богоявленского монастыря близ города Орши (Беларусь) на берегу реки Кутеинки." },
  { key: "09-19", name: "Воспоминание чуда Архистратига Михаила, бывшего в Х о нех (Кол о ссах)", year: "IV", kind: "feast", desc: "Во Фригии, недалеко от города Иераполя, в местности, называемой Херотопа, находился храм во имя Архистратига Михаила; около храма истекал целебный источник.", lifeId: "arhangel-mihail" },
  { key: "09-19", name: "Прп. Архиппа Херотопского", kind: "saint", desc: "Св. Архипп Херотопский (IV век) с 10 лет служил пономарём в храме Архистратига Михаила в Иераполе. Вёл аскетическую жизнь, обращал язычников в христианство." },
  { key: "09-19", name: "мч. Ромила Римского и с ним многих других", kind: "saint", desc: "Мч. Ромил жил в I–II веках при императоре Траяне. Будучи военачальником, он открыто осудил гонения на христиан в римской армии. Когда Траян во время восточного похода (107–115 гг.) обнаружил в войсках до 11000 христиан и отправил их в ссылк" },
  { key: "09-19", name: "сщмч. Кирилла, епископа Гортинского", kind: "saint", desc: "Сщмч. Кирилл, епископ, 50 лет возглавлявший кафедру в Гортине (Крит), пострадал во время гонений при императоре Декии (249-251 гг.) или Диоклетиане (284-305 гг.)." },
  { key: "09-19", name: "прп. Давида Ермопольского", kind: "saint", desc: "Прп. Давид Ермопольский (VI век) ‒ бывший предводитель разбойников в Египте. В старости, ужаснувшись своим грехам, он пришёл в монастырь и под угрозой возврата к разбою добился принятия в братию." },
  { key: "09-19", name: "Сщмч. Димитрия Спасского, пресвитера", kind: "saint", desc: "Сщмч. Димитрий Спасский (1877–1918) родился в семье священника. Служил в селе Усть-Нем Коми края, проповедовал на зырянском языке. В 1918 году во время погрома карательным отрядом красноармейцев был арестован за проповеди и за отказ признать советскую власть." },
  { key: "09-19", name: "Иоанна Павловского", kind: "saint", desc: "Сщмч. Иоанн Павловский (1876–1937) родился в семье священника Архангельской губернии. Служил псаломщиком, диаконом, с 1912 года ‒ священником в храмах Коми края." },
  { key: "09-19", name: "Всеволода Потеминского", kind: "saint", desc: "Сщмч. Всеволод Потёминский (1870–1937) родился в семье пономаря Вологодской губернии. Служил священником в храмах Коми края. Неоднократно преследовался властями: лишён избирательных прав, выселен из дома, трижды судим (1928, 1934, 1936)." },
  { key: "09-19", name: "Киево-Братская", year: "1654", kind: "saint", desc: "Чудотворная Киево-Братская икона Божией Матери была явлена в 1654 году и первоначально была местной в Борисоглебской церкви города Вышгорода (Киевского)." },
  { key: "09-19", name: "Арапетская", kind: "saint", desc: "Арапетская или Аравийская икона Божией Матери относится к числу наиболее древних икон, но известна только по имени. Сведений же о месте и времени ее явления не сохранилось никаких." },
  { key: "09-20", name: "Предпразднство Рождества Пресвятой Богородицы", kind: "feast", desc: "О Рождестве Богородицы и о Её родителях известно из апокрифического Протоевангелия Иакова (II век). Там рассказано, что у благочестивой семейной пары из Иерусалима, Иоакима и Анны, долгое время не было детей." },
  { key: "09-20", name: "Мч. Созонта Помпеольского (Киликийского)", kind: "saint", desc: "Мч. Созонт († ок. 304) был пастухом из Ликаонии. Обращал ко Христу других пастухов, наставляя в вере. Получив откровение, отправился в Помпеополь, где отломал руку у золотого идола в капище и раздал золото нищим." },
  { key: "09-20", name: "свт. Иоанна, архиепископа Новгородского", kind: "saint", desc: "Свт. Иоанн (XII век), архиепископ Новгородский, прославился чудесным спасением Новгорода от суздальцев в 1170 году по молитве к Богоматери. Был известен кротостью и милосердием." },
  { key: "09-20", name: "прмч. Макария Каневского, архимандрита Овручского, Переяславского", kind: "saint", desc: "Прмч. Макарий Каневский (1605–1678) родился на Волыни. Принял монашество, служил в монастырях Овруча, Пинска и Купятичей. Более 10 лет активно противостоял латино-польскому давлению на православие." },
  { key: "09-20", name: "прп. Макария Оптинского", kind: "saint", desc: "Прп. Макарий Оптинский (1788-1860), в миру Михаил Иванов, родился в семье орловских дворян. Оставив мирскую жизнь, в 1810 г. поселился в Площанской пустыни, где стал учеником старца Афанасия, последователя старца Паисия Величковского." },
  { key: "09-20", name: "Александра Пересвета", kind: "saint", desc: "Прп. Александр Пересвет ‒ брянский боярин, воевода, участник Куликовской битвы. Погиб во время этой битвы. Александр Пересвет — брянский боярин, согласно «Задонщине» (памятник древнерусской литературы конца XIV в." },
  { key: "09-20", name: "Андрея Осляби", kind: "saint", desc: "Прп. Андрей Ослябя ‒ любутский боярин, участник Куликовской битвы, впоследствии — монах. Умер не ранее 1392 года. Андрей Ослябя, был любутским боярином, опытным ратником." },
  { key: "09-20", name: "прп. Серапиона Псковского", kind: "saint", desc: "Прп. Евфросин (1386–1481) – основатель Спасо-Елеазаровского монастыря, автор уникального скитского устава, подчёркивавшего равенство братии. Прославился крайним аскетизмом, отказался от игуменства." },
  { key: "09-20", name: "Онисифора", kind: "saint", desc: "Св. апостол Онисифор (I век) ‒ один из 70 апостолов. Апостол Павел упоминает его верность и помощь (2Тим.1:16–18). Был епископом в Колофоне и Коринфе. Проповедовал в Малой Азии, где в городе Парии принял мученическую смерть: за отказ воскурить фимиам языческим богам святого привязали к диким коням и влачили по земле." },
  { key: "09-20", name: "мч. Евпсихия Кесарийского (Каппадокийского)", kind: "saint", desc: "Св. мч. Евпсихий (между 117 и 138) из Кесарии Каппадокийской пострадал при императоре Адриане. После ареста и пыток он был чудесно исцелен в темнице Ангелом." },
  { key: "09-20", name: "прп. Луки Глубокореченского (Каппадокийского), игумена", kind: "saint", desc: "Прп. Лука, третий святой игумен (с 975 г.) обители «Глубокие реки» близ Константинополя. Монастырь славился особо строгой подвижнической жизнью братии." },
  { key: "09-20", name: "Собор Алтайских святых", kind: "feast", desc: "По благословению Святейшего Патриарха Московского и всея Руси Кирилла в 2015 году был утвержден Собор Алтайских святых с днем празднования в первое воскресенье после 20 сентября." },
  { key: "09-20", name: "Собор новомучеников и исповедников Казахстанских", kind: "feast", desc: "Собор новомучеников и исповедников Казахстанских и Алма-Атинских празднуется в первое воскресенье после 3 (16) сентября. В 1930-х – 1950-х годах в Казахстане находилось одно из самых страшных подразделений ГУЛАГа – Карлаг (Карагандинский исправительно-трудовой лагерь)." },
  { key: "09-20", name: "Петра Снежницкого", kind: "saint", desc: "Сщмч. Петр Снежницкий (1880-1918) был священником в селе Большое Трифоновское Пермской губернии. В 1918 году, в период гражданских волнений, он был арестован и расстрелян большевиками." },
  { key: "09-21", name: "Рождество Пресвятой Владычицы нашей Богородицы и Приснодевы Марии", kind: "feast", desc: "О Рождестве Богородицы и о Её родителях известно из апокрифического Протоевангелия Иакова (II век). Там рассказано, что у благочестивой семейной пары из Иерусалима, Иоакима и Анны, долгое время не было детей." },
  { key: "09-21", name: "София – Премудрость Божия", year: "Киевская", kind: "saint", desc: "В Русской Православной Церкви находится много икон с изображением Софии, Премудрости Божией, — например, в Киеве, Новгороде , Вологде, Тобольске, в Москве, в Троице-Сергиевой лавре и других местах." },
  { key: "09-21", name: "Рождество Богородицы Сямская", year: "1524", kind: "saint", desc: "На Вологодчине, вдоль берегов Кубенского озера раскинулась Сямская волость, земли которой еще в XIV столетии принадлежали богатому московскому боярину Феодору Андреевичу Свибло, служившему великому князю Димитрию Донскому." },
  { key: "09-21", name: "Рождество Пресвятой Богородицы Глинская (Пустынно-Глинская)", year: "XVI", kind: "great", desc: "Эта икона «Рождество Пресвятой Богородицы» в начале XVI века чудесным образом явилась пчеловодам, которые устраивали в лесу ульи. В 1648 году на месте явления иконы основана Глинская пустынь, получившая своё название от благотворителей монастыря – рода бояр Глинских, владеющих окрестной местностью." },
  { key: "09-21", name: "Рождество Богородицы Лукиановская", year: "XVI", kind: "saint", desc: "Лукиановская икона Рождества Богородицы – из храма в честь Рождества Пресвятой Богородицы в селе Игнатьевском. В 1594 году трижды оказывалась в пустынном месте Поковитино-Раменье, недалеко от села." },
  { key: "09-21", name: "Рождество Богородицы Исааковская", year: "1659", kind: "saint", desc: "Исааковская икона Рождества Пресвятой Богородицы была явлена в 1659 году неподалеку от села Исаакиевского Ярославской епархии. Крестьяне, находившиеся в то время в лесу и увидевшие образ в ветвях ивы, хотели перенести икону в свое село, но не смогли." },
  { key: "09-21", name: "Холмская", kind: "saint", desc: "Происхождение её очень давнее. Согласно местному преданию, которое записано епископом Иаковом Сушей, она написана св. евангелистом Лукой и была привезена на земли Киевской Руси во времена князя Владимира, который после крещения получил в Константинополе множество икон." },
  { key: "09-21", name: "Знамение Курская-Коренная", kind: "saint", desc: "Курская икона «Знамение» Божией Матери — одна из древнейших икон Русской Церкви. В ХIII веке, во время татарского нашествия, когда все Русское государство испытывало величайшее бедствие, город Курск, разоренный полчищами Батыя, пришел в запустение." },
  { key: "09-21", name: "Почаевская", year: "1559", kind: "saint", desc: "История этой чудотворной иконы Богоматери неразрывно связана с Почаевским монастырём в честь Успения Пресвятой Богородицы (Украина) . На горе, где ныне расположена Успенская Почаевская лавра, в 1240 году поселились два инока." },
  { key: "09-21", name: "Леснинская", kind: "saint", desc: "Леснинская икона Божией Матери, представляющая собой вырезанное рельефом на темно-красном овальном камне изображение Пресвятой Богородицы и Богомладенца, была обретена в праздник Воздвижения Честного и Животворящего Креста Господня в 1683 году." },
  { key: "09-21", name: "Домницкая", year: "1696", kind: "saint", desc: "Первое письменное упоминание о Домницкой иконе Божией Матери относится к 1695 году, но к этому времени образ уже прославился многими чудесами. В те годы большая часть Черниговщины принадлежала Польше, а православные христиане подвергались с" },
  { key: "09-22", name: "Попразднство Рождества Пресвятой Богородицы", kind: "feast", desc: "О Рождестве Богородицы и о Её родителях известно из апокрифического Протоевангелия Иакова (II век). Там рассказано, что у благочестивой семейной пары из Иерусалима, Иоакима и Анны, долгое время не было детей." },
  { key: "09-22", name: "мч. Севериана Севастийского", kind: "saint", desc: "Св. мч. Севериан пострадал в Севастии в 320 году при императоре Ликинии. До своего мученичества он духовно поддерживал 40 Севастийских мучеников, посещая их в темнице." },
  { key: "09-22", name: "прп. Иосифа, игумена Волоцкого, чудотворца", kind: "saint", desc: "Прп. Иосиф Волоцкий (Санин, 1439/40–1515) – великий русский святой, основатель Иосифо-Волоколамского монастыря и строгого общежительного устава. Ученик прп." },
  { key: "09-22", name: "Обретение и перенесение мощей свт. Феодосия, архиепископа Черниговского", kind: "saint", desc: "Свт. Феодосий, архиепископ Черниговский (1630-е – 1696), происходил из дворянского рода. Образование получил в Киево-Братской коллегии. Принял монашество в Киево-Печерской лавре." },
  { key: "09-22", name: "Глинских святых: прпп. Василия (Кишкина), иеросхимонаха", kind: "saint", desc: "Прп. Василий (Кишкин, 1745–1831) – русский подвижник, ученик свт. Тихона Задонского. Прошел путь от послушника Саровской пустыни до старца-духовника. Подвизался в Коренской, Белобережской и Глинской пустынях, где ввел строгий афонский устав и практику непрерывной Иисусовой молитвы." },
  { key: "09-22", name: "Филарета (Данилевского), игумена", kind: "saint", desc: "Прп. Филарет (Данилевский, 1777–1841) – выдающийся подвижник и возобновитель Глинской пустыни. Приняв постриг в Софрониевой пустыни, стяжал дар умной молитвы и духовного рассуждения." },
  { key: "09-22", name: "Феодота (Левченко), монаха", kind: "saint", desc: "Прп. Феодот (Левченко, †1859) – уроженец Черниговской губернии, происходил из казаков. Не обученный грамоте, он с детства воспитывался в благочестии. Поступив в Глинскую пустынь, более семидесяти лет проходил тяжелейшее послушание на кухне, перенося побои и унижения с великим смирением." },
  { key: "09-22", name: "Макария (Шарова), иеросхимонаха", kind: "saint", desc: "Прп. Макарий (Шаров, 1802–1864), иеросхимонах, уроженец Тульской губернии, из благочестивой мещанской семьи. В 1822 году поступил в Глинскую пустынь под руководство игумена Филарета." },
  { key: "09-22", name: "Мартирия (Кириченко), монаха", kind: "saint", desc: "Прп. Мартирий (Кириченко, †1865) – уроженец Курской губернии, поступил в Глинскую пустынь в 1831 году. Проходил тяжелые послушания, особенно на мельнице." },
  { key: "09-22", name: "Евфимия (Любимченко), схимонаха", kind: "saint", desc: "Прп. Евфимий (Любимченко, 1795–1866) – уроженец Полтавской губернии, с 1818 года послушник Глинской пустыни. Много лет был келейником прп. Филарета (Данилевского), переняв его духовные наставления." },
  { key: "09-22", name: "Досифея (Колченкова), монаха", kind: "saint", desc: "Прп. Досифей (Колченков, 1811–1874) – уроженец Курской губернии, с 1840 года послушник Глинской пустыни. В 1849 году пострижен в мантию. Избегал сана иеродиакона, смиренно изобразив себя малограмотным." },
  { key: "09-22", name: "Илиодора (Голованицкого), схиархимандрита", kind: "saint", desc: "Прп. Илиодор (Голованицкий, 1795–1879) – уроженец Киевской губернии. Образование получил в Киево-Могилянской академии. Участник Заграничного похода русской армии 1813-1815 гг." },
  { key: "09-22", name: "Иннокентия (Степанова), архимандрита", kind: "saint", desc: "Прп. Иннокентий (Степанов, 1825–1888) – дворянин Курской губернии, с 1845 года насельник Глинской пустыни. С 1862 года – настоятель обители. Отличался феноменальной памятью, глубокой молитвенностью и прозорливостью." },
  { key: "09-22", name: "Луки (Швеца), схимонаха", kind: "saint", desc: "Прп. Лука (Швец, 1838-1898) ‒ глинский старец, происходивший из крестьян. 24 года нёс тяжёлые послушания на кухне и в пекарне. Приняв схиму, нёс подвиг умной молитвы, удостоившись явления Глинского образа Нерукотворного Спаса, от которого был голос с призывом читать молитвы внимательно." },
  { key: "09-23", name: "Попразднство Рождества Пресвятой Богородицы", kind: "feast", desc: "О Рождестве Богородицы и о Её родителях известно из апокрифического Протоевангелия Иакова (II век). Там рассказано, что у благочестивой семейной пары из Иерусалима, Иоакима и Анны, долгое время не было детей." },
  { key: "09-23", name: "Прп. Павла Послушливого, Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Павел Послушливый (XIII–XIV вв.) – подвижник Дальних пещер Киево-Печерского монастыря, прославившийся крайним смирением и послушанием. Безропотно выполнял самые тяжелые работы, сочетая физический труд с непрестанной молитвой." },
  { key: "09-23", name: "прп. кн. Андрея, в иночестве Иоасафа, Спасокубенского", kind: "saint", desc: "Прп. Иоасаф Каменский (Спасокубенский), в миру князь Андрей, сын заозерского князя Димитрия Васильевича. В 20 лет принял постриг в Спасо-Каменном монастыре на Кубенском озере." },
  { key: "09-23", name: "Аполлоса", kind: "saint", desc: "Апостол Аполлос, образованный александрийский иудей, был красноречивым проповедником, сведущим в Писаниях. Первоначально знал только крещение Иоанново, но в Эфесе получил более точное наставление в христианской вере от Акилы и Прискиллы." },
  { key: "09-23", name: "Климента", kind: "saint", desc: "Св. апостол Климент, епископ Сардийский, упомянут апостолом Павлом в Послании к Филиппийцам (Флп.4:3). Святой апостол Климент был епископом в Сардике (в древности богатый город Лидии в Малой Азии)." },
  { key: "09-23", name: "мч. Варипсава", kind: "saint", desc: "Мч. Варипсав (I-II вв.) – пустынник, хранитель Крови Христовой. Согласно преданию, получил сосуд с Кровью и водой, истекшими из ребра распятого Спасителя, который ранее хранился праведником Иаковом и другими отшельниками." },
  { key: "09-23", name: "блгв. царицы Греческой Пульхерии", kind: "saint", desc: "Блгв. царица Пульхерия (399–453), дочь императора Аркадия, была соправительницей и наставницей своего брата блгв. Феодосия Младшего. Прославилась благочестием и твердой защитой православия." },
  { key: "09-23", name: "Собор Липецких святых", kind: "feast", desc: "Празднование учреждено 8 июня 2010 года по благословению патриарха Московского и всея Руси Кирилла и приурочено ко дню памяти священномученика Уара, первого епископа Липецкого." },
  { key: "09-23", name: "Исмаила Кудрявцева", kind: "saint", desc: "Сщмч. Измаил Кудрявцев родился в 1876 году в Тверской губернии. После службы в армии и работы урядником принял священный сан. Во время гонений начала 30-х годов был арестован и сослан на пять лет, но досрочно освобожден по болезни." },
  { key: "09-23", name: "Евгения Попова", kind: "saint", desc: "Сщмч. Евгений Попов (1879–1937) родился в семье псаломщика, окончил духовное училище. Служил священником в Воронежской епархии. Активно противостоял обновленческому движению, за что неоднократно подвергался преследованиям." },
  { key: "09-23", name: "Иоанна Попова", kind: "saint", desc: "Сщмч. Иоанн Попов (1863–1937) родился в семье диакона в Вологодской губернии. Служил священником. Был обвинен в \"контрреволюционной агитации против колхозов, распространении пораженческих слухов и высказывании сожалений о расстреле врагов народа\"." },
  { key: "09-23", name: "Константина Колпецкого", kind: "saint", desc: "Сщмч. Константин Колпецкий (1885–1937) был дважды осуждён в 1930-х годах за неуплату налогов и отправлен в лагеря. В 1937 году его арестовали вновь и обвинили в антисоветской агитации, что он категорически отрицал на допросе." },
  { key: "09-23", name: "Петра Григорьева", kind: "saint", desc: "Сщмч. Петр Григорьев (1895–1937) неоднократно арестовывался за веру. В 1932 году был осуждён на 10 лет лагерей как руководитель «контрреволюционной организации» за сбор средств для заключённого архиепископа." },
  { key: "09-23", name: "Василия Максимова", kind: "saint", desc: "Сщмч. Василий Максимов (1887–1937) был арестован в 1937 году за активную пастырскую деятельность и проповеди. На допросах виновным себя не признал, отвергнув все обвинения в «контрреволюционной агитации»." },
  { key: "09-24", name: "Попразднство Рождества Пресвятой Богородицы", kind: "feast", desc: "О Рождестве Богородицы и о Её родителях известно из апокрифического Протоевангелия Иакова (II век). Там рассказано, что у благочестивой семейной пары из Иерусалима, Иоакима и Анны, долгое время не было детей." },
  { key: "09-24", name: "Прп. Феодоры Александрийской Младшей", kind: "saint", desc: "Прп. Феодора Александрийская, Младшая (474–491), обманом введённая в грех прелюбодеяния, в глубоком раскаянии оставила семью и тайно удалилась в мужской монастырь, приняв облик инока по имени Феодор, ибо боялась, что муж найдет ее в женской обители." },
  { key: "09-24", name: "прп. Силуана Афонского", kind: "saint", desc: "Прп. Силуан Афонский (1866-1938) с юности искал Бога. Долгие годы он молился со слезами, но не чувствовал ответа, пока не впал в отчаяние и не воскликнул: «Ты неумолим!»." },
  { key: "09-24", name: "прмц. Евдокии (Ии) Римляныни", kind: "saint", desc: "Св. мц. Ия (IV в.) – одна из 9000 христиан, захваченных персидским царем Шапуром II. Отказалась отречься от Христа, несмотря на жестокие пытки. После мучений в темнице была обезглавлена." },
  { key: "09-24", name: "прп. Евфросина Палестинского", kind: "saint", desc: "Прп. Евфросин был поваром в палестинском монастыре, смиренно и терпеливо неся своё послушание. Однажды священник обители в сонном видении спросил у Господа показать ему райские блага." },
  { key: "09-24", name: "Николая Подьякова", kind: "saint", desc: "В 1918 году протоиерей Николай Подьяков, служивший в селе Подосиновец Вологодской епархии, за чтение послания Патриарха Тихона был приговорён безбожниками к расстрелу." },
  { key: "09-24", name: "Виктора Усова", kind: "saint", desc: "Сщмч. Виктор Усов, служивший в селе Старая Яхреньга Вологодской губернии, был расстрелян 24 сентября 1918 года. После убийства настоятеля Подосиновецкой церкви отца Николая Подьякова, каратели заставили отца Виктора совершить над его телом чин отпевания." },
  { key: "09-24", name: "сщмч. Карпа Эльба, пресвитера", kind: "saint", desc: "Сщмч. Карп Эльб служил в эстонском приходе Петербурга. После революции он остался верным Патриарху Тихону и не уклонился в обновленчество. В 1937 году отца Карпа арестовали по ложному обвинению в контрреволюционной пропаганде." },
  { key: "09-24", name: "сщмч. Николая Широгорова, диакона", kind: "saint", desc: "Сщмч. Николай Широгоров, диакон, служил в храме села Ямкино Московской области. В 1937 году он был арестован по обвинению в контрреволюционной деятельности за слова в защиту веры и невинно арестованных священников." },
  { key: "09-24", name: "Казанская (Каплуновская)", year: "1689", kind: "saint", desc: "В конце XVII века в 20 верстах от города Ахтырки Харьковской губернии, в недавно возникшем сельце Каплуновке, на реке Хухре, жил благочестивый священник о." },
  { key: "09-25", name: "Отдание праздника Рождества Пресвятой Богородицы", kind: "feast", desc: "О Рождестве Богородицы и о Её родителях известно из апокрифического Протоевангелия Иакова (II век). Там рассказано, что у благочестивой семейной пары из Иерусалима, Иоакима и Анны, долгое время не было детей." },
  { key: "09-25", name: "Сщмч. Автонома, епископа Италийского", kind: "saint", desc: "Сщмч. Автоном (†313) был епископом в Италии. Во время гонений императора Диоклитиана он переселился в Вифинию, где активно проповедовал и обратил многих язычников в христианство, основав большую общину и построив храм во имя Архангела Михаила." },
  { key: "09-25", name: "прп. Афанасия Высоцкого, Серпуховского чудотворца, игумена", kind: "saint", desc: "Прп. Афанасий Высоцкий Младший был вторым игуменом Серпуховского Высоцкого монастыря. Приняв монашество, он стал образцом добродетели и молитвенного подвига для братии." },
  { key: "09-25", name: "Перенесение мощей прав. Симеона Верхотурского (Меркушинского)", kind: "saint", desc: "Праведный Симеон Верхотурский, дворянин по происхождению, оставил всё и удалился в Сибирь, где вёл жизнь смиренного странника. Он нёс слово Божие местным жителям, в том числе иноверцам-вогулам, и славился своим нестяжательством, смирением и молитвенными подвигами." },
  { key: "09-25", name: "прп. Вассиана Тиксненского", kind: "saint", desc: "Прп. Вассиан Тиксненский, бывший крестьянин, принял постриг в Суморинской обители. Стремясь к уединению, он поселился у Никольского храма на реке Тиксне, где тринадцать лет носил тяжёлые вериги и питался лишь подаянием, оставленным на оконце." },
  { key: "09-25", name: "сщмч. Иулиана Галатийского, пресвитера, и с ним 40 мучеников", kind: "saint", desc: "Сщмч. Иулиан, пресвитер IV века, был схвачен язычниками в Галатии. Отказавшись принести жертву идолам, он был подвергнут пытке на раскалённой решётке, но чудесным образом остался невредим." },
  { key: "09-25", name: "сщмч. Феодора, епископа Александрийского", kind: "saint", desc: "Сщмч. Феодор, епископ Александрийский, был пламенным проповедником, вызвавшим ненависть местных язычников. Во время проповеди они захватили его, подвергли издевательствам и сбросили со скалы в море, но волны чудесно вынесли его невредимым на берег." },
  { key: "09-25", name: "сщмч. Корнута, епископа Никомидийского (Иконийского)", kind: "icon", desc: "Сщмч. Корнут, епископ Никомидийский, добровольно явился к гонителям во время преследования христиан при императоре Декии. После жестоких истязаний, когда его водили по городу со связанными верёвками ногами, святой был обезглавлен." },
  { key: "09-25", name: "Феодора Лебедева", kind: "saint", desc: "Сщмч. Феодор Лебедев, служивший во Владимирской губернии, был арестован в 1937 году по обвинению в контрреволюционной деятельности. Несмотря на трёхсуточные непрерывные допросы и давление следствия, он категорически отверг все ложные обвинения, отказавшись признать себя виновным или оговорить других." },
  { key: "09-25", name: "Иоанна Прудентова", kind: "saint", desc: "Сщмч. Иоанн Прудентов, потомственный священник, всю жизнь посвятил служению Богу и людям. Он был талантливым педагогом, организовал школу и детский хор, помогал крестьянам." },
  { key: "09-25", name: "Николая Житова", kind: "saint", desc: "Сщмч. Николай Житов, служивший в сельских храмах Рязанской губернии, был арестован в 1937 году по ложному обвинению в контрреволюционной деятельности. Несмотря на давление следствия, он категорически отверг все обвинения." },
  { key: "09-25", name: "мч. Алексия (Ворошина), Ёлнатского", kind: "saint", desc: "Мч. Алексей Ворошин, Ёлнатский (1886-1937) ‒ крестьянин из Костромской губернии. Приняв подвиг юродства в 1928 году, он странствовал по деревням, предсказывая будущие беды: аресты, раскулачивание, войну." },
  { key: "09-26", name: "Память освящения храма Воскресения Христова в Иерусалиме (Воскресение слов у щее)", year: "335", kind: "feast", desc: "26 сентября – Освящение (обновление) храма Воскресения Христова в Иерусалиме (Воскресение словущее). Престольный праздник сегодня отмечается в храмах нескольких сел Нижегородской области: Воскресенское, Водоватово (Арзамасский район), Юрьево (Гагинский район) - и кафедральном соборе города Арзамаса." },
  { key: "09-26", name: "Предпразднство Воздвижения Честного и Животворящего Креста Господня", kind: "feast", desc: "Битбунов Г.С. Воздвижение Креста Господня. Событие праздника и его эортологическая динамика В этот день православные христиане вспоминают два события. Как говорит Священное Предание, Крест был найден в 326 году в Иерусалиме." },
  { key: "09-26", name: "сщмч. Корнилия Сотника, епископа", kind: "saint", desc: "Св. Корнилий, первоначально язычник, был благочестивым и милостивым мужем, о чём свидетельствует евангелист Лука (Деян.10:1). Однажды Корнилию явился ангел, который велел послать людей в Иоппию и призвать Симона, называемого Петром." },
  { key: "09-26", name: "Селевка Галатийского", kind: "saint", desc: "Св. мч. Селевк пострадал в III веке в Галатии. После жестоких мучений он был брошен на растерзание диким зверям вместе со своей супругой. Святые мученики Селевк, Стратоник, Кронид, Леонтий и Серапион пострадали за христианскую веру в III веке." },
  { key: "09-26", name: "Стратора (Стратоника)", kind: "saint", desc: "Св. Стратоника (III в.) по приказу вифинского правителя после пыток привязали к двум пригнутым стволам дерева. Тело его было разорвано на две части. Святые мученики Селевк, Стратоник, Кронид, Леонтий и Серапион пострадали за христианскую веру в III веке." },
  { key: "09-26", name: "сщмч. Иулиана Галатийского, пресвитера", kind: "saint", desc: "Сщмч. Иулиан, пресвитер IV века, был схвачен язычниками в Галатии. Отказавшись принести жертву идолам, он был подвергнут пытке на раскалённой решётке, но чудесным образом остался невредим." },
  { key: "09-26", name: "прп. Петра в Атрое", kind: "saint", desc: "Прп. Петр из Атрои всю жизнь провёл в строгом посте и непрестанной молитве. Подвизаясь близ Олимпа Азийского, он стяжал дар чудотворения. Святой мирно скончался во время патриаршества Тарасия Константинопольского (784–806 гг.)." },
  { key: "09-26", name: "вмц. Кетевани (Кетеван), царицы Кахетинской (1624)", kind: "saint", desc: "Вмц. Кетевана, царица Кахетинская, прославилась глубоким благочестием. Добровольно став заложницей у персидского шаха Аббаса I, чтобы спасти свой народ, десять лет провела в темнице." },
  { key: "09-26", name: "Николая Васюковича, диакона", kind: "saint", desc: "Сщмч. Николай Васюкович, диакон, служивший в храме села Литвяны, был арестован в 1937 году за открытое осуждение богоборческой власти и отказ от участия в государственном займе." },
  { key: "09-27", name: "Воздвижение Честного и Животворящего Креста Господня", kind: "feast", desc: "Битбунов Г.С. Воздвижение Креста Господня. Событие праздника и его эортологическая динамика В этот день православные христиане вспоминают два события. Как говорит Священное Предание, Крест был найден в 326 году в Иерусалиме." },
  { key: "09-27", name: "Преставление свт. Иоанна Златоуста, архиепископа Константинопольского", kind: "saint", desc: "Свт. Иоанн Златоуст, архиепископ Константинопольский (IV–V вв.), ‒ величайший проповедник и богослов, один из трёх вселенских святителей. Прославился красноречием, толкованиями Св.", lifeId: "ioann-zlatoust" },
  { key: "09-27", name: "Леснинская", kind: "saint", desc: "Леснинская икона Божией Матери, представляющая собой вырезанное рельефом на темно-красном овальном камне изображение Пресвятой Богородицы и Богомладенца, была обретена в праздник Воздвижения Честного и Животворящего Креста Господня в 1683 году." },
  { key: "09-28", name: "Попразднство Воздвижения Честного и Животворящего Креста Господня", kind: "feast", desc: "Битбунов Г.С. Воздвижение Креста Господня. Событие праздника и его эортологическая динамика В этот день православные христиане вспоминают два события. Как говорит Священное Предание, Крест был найден в 326 году в Иерусалиме." },
  { key: "09-28", name: "Вмч. Никиты Готфского", kind: "saint", desc: "Вмч. Никита, готф по происхождению, принял крещение и стал ревностным проповедником христианства среди соплеменников. После возвращения к власти язычников св." },
  { key: "09-28", name: "Обретение мощей свт. Акакия исп., епископа Мелитинского", kind: "saint", desc: "Сщмч. Акакий, епископ Мелитинский, был ревностным проповедником христианства. Во время гонений императора Декия (III в.) его схватили и после жестоких пыток бросили в тюрьму." },
  { key: "09-28", name: "Максима", kind: "saint", desc: "Свв. мученики Максим, Асклиада и Феодот пострадали в начале IV века во Фракии. Знатные христиане Максим и Асклиада были схвачены правителем Тирисом за исповедание веры." },
  { key: "09-28", name: "Феодота", kind: "saint", desc: "Свв. мученики Максим, Асклиада и Феодот пострадали в начале IV века во Фракии. Знатные христиане Максим и Асклиада были схвачены правителем Тирисом за исповедание веры." },
  { key: "09-28", name: "Асклиады (Асклипиодоты)", kind: "saint", desc: "Свв. мученики Максим, Асклиада и Феодот пострадали в начале IV века во Фракии. Знатные христиане Максим и Асклиада были схвачены правителем Тирисом за исповедание веры." },
  { key: "09-28", name: "мч. Порфирия Ефесского", kind: "saint", desc: "Св. мученик Порфирий, актёр, во время представления в Ефесе (361 г.) по сценарию должен был глумиться над таинством Крещения. Однако, произнеся крещальную формулу при погружении в воду, он чудесным образом уверовал во Христа и открыто исповедал себя христианином." },
  { key: "09-28", name: "Обретение мощей первомученика архидиакона Стефана", kind: "saint", desc: "Св. архидиакон Стефан, первый христианский мученик, был одним из семи диаконов, избранных апостолами. Проповедуя с дерзновением, он обличал иудеев в отвержении Мессии ‒ Христа.", lifeId: "stephan" },
  { key: "09-28", name: "прп. Филофея, пресвитера, в Малой Азии", kind: "saint", desc: "Св. пресвитер Филофей, чудотворец X века, служил в вифинском селении Мравино. Приняв сан священника, он всецело посвятил себя молитве, посту и делам милосердия, питая голодных и помогая нуждающимся." },
  { key: "09-28", name: "свт. Иосифа, епископа Алавердского (570)", kind: "saint", desc: "Свт. Иосиф Алавердский, один из 13-и сирийских отцов, пришёл в Грузию в VI веке со своим учителем, св. Иоанном Зедазнийским, и поселился в безлюдной Алавердской степи." },
  { key: "09-28", name: "свт. Симеона, архиепископа Солунского", kind: "saint", desc: "Свт. Симеон (†1429) ‒ архиепископ Солунский, был богословом и защитником Православия. Родился в Константинополе, принял монашество, был приверженцем исихазма и учения св." },
  { key: "09-28", name: "Сщмч. Иоанна Ильинского, пресвитера,", kind: "saint", desc: "Сщмч. Иоанн Ильинский (1846–1918) ‒ священник села Томылово Симбирской губернии, служивший на одном приходе 45 лет. 13 сентября 1918 года, после отступления белочехов, был арестован красноармейцами во время исполнения пастырского долга (шёл с Дарами к больной)." },
  { key: "09-28", name: "прмц. Евдокии (Ткаченко), монахини", kind: "saint", desc: "Преподобномученица Евдокия (Ткаченко) подвизалась в Иверско-Серафимовском монастыре в городе Верном Семиреченской области; монастырь был образован в 1910 году; первой игуменией стала монахиня Паисия, подвизавшаяся до этого в Ставропольском Иоанно-Мариинском монастыре." },
  { key: "09-28", name: "Андрея Ковалева", kind: "saint", desc: "Сщмч. Андрей Ковалев (1871–1921) был священником на Кубани и в Ставрополье, служил в различных храмах и преподавал в церковноприходских школах. После революции переехал в Краснодар." },
  { key: "09-29", name: "Попразднство Воздвижения Честного и Животворящего Креста Господня", kind: "feast", desc: "Битбунов Г.С. Воздвижение Креста Господня. Событие праздника и его эортологическая динамика В этот день православные христиане вспоминают два события. Как говорит Священное Предание, Крест был найден в 326 году в Иерусалиме." },
  { key: "09-29", name: "Вмц. Евфимии Всехвальной", kind: "saint", desc: "Св. вмц. Евфимия жила в Халкидоне в III веке. Во время гонений при императоре Диоклетиане она была арестована за отказ отречься от христианской веры и претерпела жестокие мучения, оставаясь непоколебимой." },
  { key: "09-29", name: "Перенесение мощей прав. Алексия Московского (Мечёва)", kind: "saint", desc: "Св. прав. Алексий Мечёв (1859-1923) родился в Москве в семье регента. По благословению матери стал священником. 40 лет прослужил в малоприходном храме свт.", lifeId: "aleksey-mechov" },
  { key: "09-29", name: "Свт. Киприана, митрополита Киевского, Московского и всея Руси, чудотворца", kind: "saint", desc: "Серб (или болгарин), афонский монах. В 1375 г. поставлен митрополитом Киевским и всея Руси, управляя юго-западной частью Церкви. С 1390 г. – объединил кафедру в Москве." },
  { key: "09-29", name: "свт. Фотия, митрополита Киевского, Московского и всея Руси, чудотворца", kind: "saint", desc: "Грек из Монемвасии. В 1408 г. избран Константинополем на русскую кафедру. Перенёс митрополичью кафедру из Киева в Москву (1410), укрепив духовный центр Руси." },
  { key: "09-29", name: "прп. Кукши Одесского, исп.", kind: "saint", desc: "Прписп. Кукша Одесский (Величко) родился в 1875 году. С юности стремился к монашеству, подвизался на Афоне, затем в Киево-Печерской лавре. В годы гонений был арестован и провёл 8 лет в лагерях и ссылке, сохраняя веру и поддерживая заключённых." },
  { key: "09-29", name: "мц. Севастианы Гераклейской", kind: "saint", desc: "Св. мц. Севастиана, ученица апостола Павла, пострадала за веру во Христа при императоре Домициане. После жестоких истязаний, включая избиение и раскалённую печь, из которой вышла невредимой, её отправили в Гераклею." },
  { key: "09-29", name: "мц. Мелитины Маркианопольской", kind: "saint", desc: "Св. мц. Мелитина, жившая в Маркианополе, прославилась даром чудотворения и ревностной проповедью христианства. Она сокрушила идолов Аполлона и Геркулеса и обратила многих язычников в веру, включая супругу городского начальника." },
  { key: "09-29", name: "прп. Дорофея, пустынника Египетского", kind: "saint", desc: "Прп. Дорофей Египетский 60 лет подвизался в Скитской пустыне, ведя крайне аскетическую жизнь. Он питался лишь хлебом и травами раз в сутки, спал урывками за работой, а дни проводил в молитве, плетении корзин и сборе камней для строительства келий другим отшельникам." },
  { key: "09-29", name: "мц. Людмилы, кн. Чешской", kind: "saint", desc: "Мц. Людмила, княгиня Чешская, приняла крещение от свт. Мефодия, архиепископа Моравского, и вместе с мужем заботилась о христианском просвещении народа." },
  { key: "09-29", name: "прп. Прокопия, игумена Сазавского", kind: "saint", desc: "Прп. Прокопий Сазавский, славянский подвижник из Богемии, основал обитель на реке Сазаве, где ввел богослужение на славянском языке. Несмотря на покровительство чешских князей, встречал сопротивление латинского духовенства." },
  { key: "09-29", name: "Сщмч. Григория Раевского, пресвитера", kind: "saint", desc: "Сщмч. Григорий Раевский, священник Успенского храма в селе Завидово, был арестован в 1937 году по ложному обвинению в контрреволюционной деятельности. Несмотря на отсутствие доказательств и лояльные показания прихожан, он был приговорён тройкой НКВД к расстрелу." },
  { key: "09-29", name: "сщмч. Сергия Лосева, пресвитера", kind: "saint", desc: "Сщмч. Сергий Лосев, священник храма в селе Капотня, был арестован в 1937 году по ложным обвинениям в контрреволюционной деятельности и организации сборищ." },
  { key: "09-29", name: "Пр и зри на смирение", year: "1420", kind: "saint", desc: "Икона Божией Матери, именуемая «Призри на смирение», была явлена в 1426 году в Псковской земле, на озере Каменном. Обстоятельства чудесного явления неизвестны, но можно сделать предположение о том, что святая икона была обретена псковитянам" },
  { key: "09-30", name: "Попразднство Воздвижения Честного и Животворящего Креста Господня", kind: "feast", desc: "Битбунов Г.С. Воздвижение Креста Господня. Событие праздника и его эортологическая динамика В этот день православные христиане вспоминают два события. Как говорит Священное Предание, Крест был найден в 326 году в Иерусалиме." },
  { key: "09-30", name: "Феодотии", kind: "saint", desc: "Св. мц. Феодотия (ок. 230) из Каппадокии пострадала за веру во Христа при императоре Александре Севере. Правитель Симвликий, безуспешно пытаясь склонить её к отречению, подверг святую жестоким пыткам: её рвали железными крючьями, бросали в раскалённую печь, но Господь чудесно сохранял её невредимой." },
  { key: "09-30", name: "Агафоклии", kind: "saint", desc: "Св. мц. Агафоклия, рабыня-христианка, восемь лет терпела жестокие гонения от своей языческой госпожи Павлины. Её избивали, заставляли ходить босиком по камням, сломали рёбра молотком и отрезали язык, но она не отреклась от веры." },
  { key: "09-30", name: "свт. Иоакима (Пани), патриарха Александрийского", kind: "saint", desc: "Свт. Иоаким, патриарх Александрийский (†1567), мудро управлял паствой при османском владычестве, сохранив церковные привилегии. Прославился великими чудесами: по его молитве во время эпидемии чумы сдвинулась гора близ Каира, а также он остался невредим, выпив смертельный яд." },
  { key: "09-30", name: "прмц. Ирины Фроловой, послушницы", kind: "saint", desc: "Прмц. Ирина Фролова, послушница Спасо-Бородинского монастыря, после его закрытия осталась жить на территории обители, исполняя послушание «стеречь монастырь»." },
  { key: "09-30", name: "мч. Иоанна Короткова", kind: "saint", desc: "Мч. Иоанн Коротков (1885–1941), крестьянин Ярославской губернии, отказался вступать в колхоз и вёл единоличное хозяйство. Позже, за исповедание христианской веры и проповедь был уволен с работы при больнице, а в 1937 году арестован." },
  { key: "09-30", name: "прмц. Александры Хворостянниковой, послушницы", kind: "saint", desc: "Прмц. Александра Хворостянникова (1886–1943), послушница, уроженка Московской губернии, в 1915 году поступила в женскую монастырскую общину. После её закрытия работала на текстильной фабрике в Серпухове." },
  { key: "09-30", name: "Цареградская", year: "1071", kind: "saint", desc: "Цареградской называют две значительно отличающихся друг от друга иконы. По преданию, Цареградская икона Божией Матери, память которой празднуется 8 мая (25 апреля по старому стилю), – одна из икон, написанных святым апостолом и евангелистом Лукой." },
  { key: "09-30", name: "Макарьевская", year: "1442", kind: "saint", desc: "Макарьевская икона Божией Матери «Одигитрия» была явлена 17 сентября 1442 года преподобному Макарию Унженскому чудотворцу (&dagger; 1444), который подвизался в посте и молитве на пустынных берегах реки Унжи во времена княжения Василия Темного (1425–1462)." },
];
